INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2007_25_pasal_35', 'Pasal 35', 'ARTICLE', 'Perjanjian internasional, baik bilateral, regional, maupun multilateral, dalam bidang penanaman modal yang telah disetujui oleh Pemerintah Indonesia sebelum Undang-Undang ini berlaku, tetap berlaku sampai dengan berakhirnya perjanjian tersebut.', NULL, '{"law_id":"uu_2007_25","pasal":"35","heading":null,"bab":"XVII","bab_heading":"KETENTUAN PERALIHAN","sort_order":138}', '/akn/id/act/uu/2007/25#pasal-35', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2007_25_pasal_36', 'Pasal 36', 'ARTICLE', 'Rancangan perjanjian internasional, baik bilateral, regional, maupun multilateral, dalam bidang penanaman modal yang belum disetujui oleh Pemerintah Indonesia pada saat Undang-Undang ini berlaku wajib disesuaikan dengan ketentuan Undang-Undang ini.', NULL, '{"law_id":"uu_2007_25","pasal":"36","heading":null,"bab":"XVII","bab_heading":"KETENTUAN PERALIHAN","sort_order":139}', '/akn/id/act/uu/2007/25#pasal-36', 'diubah', NULL, NULL, NULL, NULL);
