INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2007_25_pasal_39', 'Pasal 39', 'ARTICLE', 'Semua Ketentuan peraturan perundang-undangan yang berkaitan secara langsung dengan penanaman modal wajib mendasarkan dan menyesuaikan pengaturannya pada Undang-Undang ini.', NULL, '{"law_id":"uu_2007_25","pasal":"39","heading":null,"bab":"XVIII","bab_heading":"KETENTUAN PENUTUP","sort_order":147}', '/akn/id/act/uu/2007/25#pasal-39', 'diubah', NULL, NULL, NULL, NULL);
