INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2007_40_pasal_155', 'Pasal 155', 'ARTICLE', 'Ketentuan mengenai tanggung jawab Direksi dan/atau Dewan Komisaris atas kesalahan dan kelalaiannya yang diatur dalam Undang-Undang ini tidak mengurangi ketentuan yang diatur dalam Undang-Undang tentang Hukum Pidana.', NULL, '{"law_id":"uu_2007_40","pasal":"155","heading":null,"bab":"XII","bab_heading":"KETENTUAN LAIN-LAIN","sort_order":695}', '/akn/id/act/uu/2007/40#pasal-155', 'diubah', NULL, NULL, NULL, NULL);
