INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2007_40_pasal_158', 'Pasal 158', 'ARTICLE', 'Pada saat Undang-Undang ini mulai berlaku, Perseroan yang tidak memenuhi ketentuan sebagaimana dimaksud dalam Pasal 36, dalam jangka waktu 1 (satu) tahun harus menyesuaikan dengan ketentuan Undang-Undang ini.', NULL, '{"law_id":"uu_2007_40","pasal":"158","heading":null,"bab":"XIII","bab_heading":"KETENTUAN PERALIHAN","sort_order":707}', '/akn/id/act/uu/2007/40#pasal-158', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2007_40_pasal_159', 'Pasal 159', 'ARTICLE', 'Peraturan pelaksanaan dari Undang-Undang Nomor 1 Tahun 1995 tentang Perseroan Terbatas dinyatakan tetap berlaku sepanjang tidak bertentangan atau belum diganti dengan yang baru berdasarkan Undang-Undang ini.', NULL, '{"law_id":"uu_2007_40","pasal":"159","heading":null,"bab":"XIV","bab_heading":"KETENTUAN PENUTUP","sort_order":709}', '/akn/id/act/uu/2007/40#pasal-159', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2007_40_pasal_160', 'Pasal 160', 'ARTICLE', 'Pada saat Undang-Undang ini mulai berlaku, Undang-Undang Nomor 1 Tahun 1995 tentang Perseroan Terbatas (Lembaran Negara Republik Indonesia Tahun 1995 Nomor 13, Tambahan Lembaran Negara Republik Indonesia Nomor 3587), dicabut dan dinyatakan tidak berlaku.', NULL, '{"law_id":"uu_2007_40","pasal":"160","heading":null,"bab":"XIV","bab_heading":"KETENTUAN PENUTUP","sort_order":710}', '/akn/id/act/uu/2007/40#pasal-160', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2007_40_pasal_161', 'Pasal 161', 'ARTICLE', 'Undang-Undang ini mulai berlaku pada tanggal diundangkan.', NULL, '{"law_id":"uu_2007_40","pasal":"161","heading":null,"bab":"XIV","bab_heading":"KETENTUAN PENUTUP","sort_order":711}', '/akn/id/act/uu/2007/40#pasal-161', 'diubah', NULL, NULL, NULL, NULL);
