INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_22c', 'Pasal 22C', 'ARTICLE', 'Ketentuan lebih lanjut mengenai Perizinan Berusaha terkait pemanfaatan di laut diatur dalam Peraturan Pemerintah.', NULL, '{"law_id":"uu_2023_6","pasal":"22C","heading":null,"bab":null,"bab_heading":null,"sort_order":252}', '/akn/id/act/uu/2023/6#pasal-22C', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_26a', 'Pasal 26A', 'ARTICLE', 'Dalam rangka penanaman modal asing, pemanfaatan pulau-pulau kecil dan pemanfaatan perairan di sekitarnya harus memenuhi Perizinan Berusaha dari Pemerintah Pusat dan sesuai dengan ketentuan peraturan perundang-undangan di bidang penanaman modal.', NULL, '{"law_id":"uu_2023_6","pasal":"26A","heading":null,"bab":null,"bab_heading":null,"sort_order":254}', '/akn/id/act/uu/2023/6#pasal-26A', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_50', 'Pasal 50', 'ARTICLE', 'Pemerintah Pusat atau Pemerintah Daerah sesuai dengan kewenangannya memberikan dan mencabut Perizinan Berusaha terkait pemanfaatan di laut di wilayah Perairan Pesisir.', NULL, '{"law_id":"uu_2023_6","pasal":"50","heading":null,"bab":null,"bab_heading":null,"sort_order":257}', '/akn/id/act/uu/2023/6#pasal-50', 'diubah', NULL, NULL, NULL, NULL);
