INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_71_a24451671', 'Pasal 71', 'ARTICLE', 'Pemanfaatan rrrang perairan dan Sumber Daya Pesisir dan Pulau-Pulau Kecil yang tidak memiliki kesesuaian kegiatan pemanfaatan ruang laut yang diberikan sebagaimana dimaksud dalam Pasal 16 ayat (21 dan Perizinan Berusaha sebagaimana dimaksud dalam Pasal 19 ayat (1) dikenai sanksi administratif.', NULL, '{"law_id":"uu_2023_6","pasal":"71","heading":null,"bab":null,"bab_heading":null,"sort_order":267}', '/akn/id/act/uu/2023/6#pasal-71~2', 'diubah', NULL, NULL, NULL, NULL);
