INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_73a', 'Pasal 73A', 'ARTICLE', 'Setiap Orang yang memanfaatkan Pulau Kecil dan perairan di sekitarnya dalam rangka penanaman modal asing yang tidak memiliki Perizinan Berusaha sebagaimana dimaksud dalam Pasal 26A yang mengakibatkan perubahan fungsi ruang dipidana dengan pidana penjara paling lama 4 (empat) tahun dan pidana denda paling banyak Rp2.000.000.000,00 (dua miliar rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"73A","heading":null,"bab":null,"bab_heading":null,"sort_order":273}', '/akn/id/act/uu/2023/6#pasal-73A', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_75_a24451679', 'Pasal 75', 'ARTICLE', 'Setiap Orang yang memanfaatkan ruang dari perairan yang tidak memiliki kesesuaian kegiatan pemanfaatan ru€Lng laut sebagaimana dimaksud dalam Pasal 16 ayat (21 yang mengakibatkan perubahan fungsi ruang dipidana dengan pidana penjara paling lama 3 (tiga) tahun dan pidana denda paling banyak Rp500.000.000,00 (lima ratus juta rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"75","heading":null,"bab":null,"bab_heading":null,"sort_order":275}', '/akn/id/act/uu/2023/6#pasal-75~2', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_78a', 'Pasal 78A', 'ARTICLE', 'Kawasan Konservasi di Wilayah Pesisir dan Pulau-Pulau Kecil yang telah ditetapkan melalui peraturan perundang-undangan menjadi kewenangan Pemerintah Pusat.', NULL, '{"law_id":"uu_2023_6","pasal":"78A","heading":null,"bab":null,"bab_heading":null,"sort_order":278}', '/akn/id/act/uu/2023/6#pasal-78A', 'diubah', NULL, NULL, NULL, NULL);
