INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_88', 'Pasal 88', 'ARTICLE', 'Setiap Orang yang tindakannya, usahanya, dan/atau kegiatannya menggunakan 83, menghasilkan danf atau mengelola Limbah 83, dan/atau yang menimbulkan Ancaman Serius terhadap Lingkungan Hidup bertanggung jawab mutlak atas kerugian yang terjadi dari usaha dan/atau kegiatannya.', NULL, '{"law_id":"uu_2023_6","pasal":"88","heading":null,"bab":null,"bab_heading":null,"sort_order":483}', '/akn/id/act/uu/2023/6#pasal-88', 'diubah', NULL, NULL, NULL, NULL);
