INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_111', 'Pasal 111', 'ARTICLE', 'Pejabat pemberi Persetujuan Lingkungan yang menerbitkan Persetujuan Lingkungan sebagaimana dimaksud dalam Pasal 24 ayat (a) dan Pasal 34 ayat (3) tanpa dilengkapi dengan Amdal atau UKL-UPL dipidana dengan pidana penjara paling lama 3 (tiga) tahun dan pidana denda paling banyak Rp3.000.000.000,00 (tiga miliar rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"111","heading":null,"bab":null,"bab_heading":null,"sort_order":490}', '/akn/id/act/uu/2023/6#pasal-111', 'diubah', NULL, NULL, NULL, NULL);
