INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_6_a24452029', 'Pasal 6', 'ARTICLE', 'Untuk melakukan Praktik Arsitek, seseorang wajib memiliki Surat Tanda Registrasi Arsitek.', NULL, '{"law_id":"uu_2023_6","pasal":"6","heading":null,"bab":null,"bab_heading":null,"sort_order":625}', '/akn/id/act/uu/2023/6#pasal-6~4', 'diubah', NULL, NULL, NULL, NULL);
