INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_89', 'Pasal 89', 'ARTICLE', 'Setiap Orang yang melakukan penanganan dan pengolahan Ikan yang tidak memenuhi dan tidak menerapkan persyaratan kelayakan pengolahan lkan, sistem jaminan mutu, dan keamanan hasil Perikanan sebagaimana dimaksud dalam Pasal 20 ayat (3) yang menimbulkan korban terhadap kesehatan manusia dipidana dengan pidana penjara paling lama 1 (satu) tahun dan pidana denda paling banyak Rp80O.00O.000,00 (delapan ratus juta rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"89","heading":null,"bab":null,"bab_heading":null,"sort_order":736}', '/akn/id/act/uu/2023/6#pasal-89', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_92', 'Pasal 92', 'ARTICLE', 'Setiap Orang yang dengan sengaja di wilayah Pengelolaan Perikanan Negara Republik Indonesia melakukan usaha Perikanan yang tidak memiliki Perizinan Berusaha sebagaimana dimaksud dalam Pasal 26 ayat (f) dipidana dengan pidana penjara paling lama 8 (delapan) tahun dan pidana denda paling banyak Rpl.500.O00.000,00 (satu miliar lima ratus juta rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"92","heading":null,"bab":null,"bab_heading":null,"sort_order":738}', '/akn/id/act/uu/2023/6#pasal-92', 'diubah', NULL, NULL, NULL, NULL);
