INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_94', 'Pasal 94', 'ARTICLE', 'Setiap Orang yang memiliki dan/ atau mengoperasikan kapal pengangkut Ikan berbendera Indonesia atau berbendera asing di wilayah Pengelolaan Perikanan Negara Republik Indonesia yang melakukan pengangkutan Ikan atau kegiatan yang terkait yang tidak memenuhi Perizinan Berusaha sebagaimana dimaksud dalam Pasal 28 ayat (1) dan ayat (21 dipidana dengan pidana penjara paling lama 5 (lima) tahun dan pidana denda paling banyak Rp1.500.O0O.00O,00 (satu miliar lima ratus juta rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"94","heading":null,"bab":null,"bab_heading":null,"sort_order":744}', '/akn/id/act/uu/2023/6#pasal-94', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_94a', 'Pasal 94A', 'ARTICLE', 'Setiap Orang yang memalsukan dokumen Perizinan Berusaha, menggunakan Perizinan Berusaha palsu, menggunakan Perizinan Berusaha milik kapal lain atau orang lain, dan/ atau menggandakan Perizinan Berusaha untuk digunakan oleh kapal lain dan/ atau kapal milik sendiri sebagaimana dimaksud dalam Pasal 28A dipidana dengan pidana penjara paling lama 7 (tujuh) tahun dan pidana denda paling banyak Rp3.000.0OO.000,00 (tiga miliar rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"94A","heading":null,"bab":null,"bab_heading":null,"sort_order":746}', '/akn/id/act/uu/2023/6#pasal-94A', 'diubah', NULL, NULL, NULL, NULL);
