INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_98', 'Pasal 98', 'ARTICLE', 'Nakhoda Kapal Perikanan yang tidak memiliki persetujuan berlayar sebagaimana dimaksud dalam Pasal 42 ayat (3) dipidana dengan pidana pedara paling lama I (satu) tahun dan pidana denda paling banyak Rp20O.00O.000,OO (dua ratus juta rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"98","heading":null,"bab":null,"bab_heading":null,"sort_order":755}', '/akn/id/act/uu/2023/6#pasal-98', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_100c', 'Pasal 100C', 'ARTICLE', 'Dalam hal tindak pidana sebagaimana dimaksud dalam Pasal 7 ayat (21huruf a, huruf b, huruf c, huruf d, huruf f, hurufg, hurufh, hurufi, hurufj, hurufk, hurufl, atau huruf m dilakukan oleh Nelayan Kecil dan/ atau Pembudi Daya-Ikan Kecil dipidana dengan pidana denda paling banyak Rp100.00O.000,O0 (seratus juta rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"100C","heading":null,"bab":null,"bab_heading":null,"sort_order":758}', '/akn/id/act/uu/2023/6#pasal-100C', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_101', 'Pasal 101', 'ARTICLE', 'Dalam hal tindak pidana sebagaimana dimaksud dalam Pasal 84 ayat (1), Pasal 84 ayat (3), Pasal 84 ayat (4), Pasal 85, Pasal 86, Pasal 87, Pasal 88, Pasal 89, Pasal 90, Pasal 91, Pasal 92, Pasal 93, Pasal 94, atau Pasal 94A dilakukan oleh Korporasi, tuntutan dan sanksi pidananya dijatuhkan terhadap pengurusnya dan terhadap Korporasi dipidana denda dengan tambahan pemberatan 1/3 (sepertiga) dari pidana denda yang dijatuhkan.', NULL, '{"law_id":"uu_2023_6","pasal":"101","heading":null,"bab":null,"bab_heading":null,"sort_order":760}', '/akn/id/act/uu/2023/6#pasal-101', 'diubah', NULL, NULL, NULL, NULL);
