INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_30_a24452574', 'Pasal 30', 'ARTICLE', 'Dalam rangka pemberdayaan ekonomi masyarakat, setiap badan usaha milik negara, badan usaha milik daerah, dan badan usaha milik swasta yang memperoleh Perizinan Berusaha pemanfaatan Hutan wajib bekerja sama dengan koperasi masyarakat setempat.', NULL, '{"law_id":"uu_2023_6","pasal":"30","heading":null,"bab":null,"bab_heading":null,"sort_order":1170}', '/akn/id/act/uu/2023/6#pasal-30~5', 'diubah', NULL, NULL, NULL, NULL);
