INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_109_a24453238', 'Pasal 109', 'ARTICLE', 'Produsen atau Importir yang memperdagangkan Barang terkait dengan keamanan, keselamatan, kesehatan, dan/atau lingkungan hidup yang tidak didaftarkan kepada Pemerintah Pusat sebagaimana dimaksud dalam Pasal 32 ayat (1) yang mengakibatkan timbulnya korban/kerusakan terhadap keamanan, keselamatan, kesehatan, danlatau lingkungan hidup dipidana dengan pidana penjara paling lama 1 (satu) tahun alan pidana denda paling banyak dan f Rp5.000.000.000,00 (lima miliar rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"109","heading":null,"bab":null,"bab_heading":null,"sort_order":1834}', '/akn/id/act/uu/2023/6#pasal-109~2', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_116', 'Pasal 116', 'ARTICLE', 'Setiap Pelaku Usaha yang menyelenggarakan pameran dagang dengan mengikutsertakan peserta dan/ atau produk yang dipromosikan berasal dari luar negeri yang tidak mendapatkan Perizinan Berusaha dari Pemerintah Pusat sebagaimana dimaksud dalam Pasil 77 ayal (21 dipidana dengan pidana penjara paling lama 3 (tiga) tahun atau pidana denda paling banyak dan/ Rp5.O00.0OO.000,00 (lima miliar rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"116","heading":null,"bab":null,"bab_heading":null,"sort_order":1836}', '/akn/id/act/uu/2023/6#pasal-116', 'diubah', NULL, NULL, NULL, NULL);
