INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_9_a24453581', 'Pasal 9', 'ARTICLE', 'Dalam melaksanakan kewenangan sebagaimana dimaksud dalam Pasal 5 sampai dengan Pasal 8, Pemerintah Pusat dan/ atau Pemerintah Daerah sesuai dengan norma, standar, prosedur, dan kriteria yang ditetapkan oleh Pemerintah Pusat dapat melibatkan masyarakat Jasa Konstruksi.', NULL, '{"law_id":"uu_2023_6","pasal":"9","heading":null,"bab":null,"bab_heading":null,"sort_order":2177}', '/akn/id/act/uu/2023/6#pasal-9~5', 'diubah', NULL, NULL, NULL, NULL);
