INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_302', 'Pasal 302', 'ARTICLE', 'Setiap orang yang mengemudikan Kendaraan Bermotor Umum angkutan orang yang tidak berhenti selain di tempat yang telah ditentukan, mengetem, menurunkan penumpang selain di tempat pemberhentian, atau melewati jaringan jalan selain yang ditentukan dalam trayek yang telah disetujui dalam Perizinan Berusaha sebagaimana dimaksud dalam Pasal 126 dipidana dengan pidana kurungan paling lama 1 (satu) bulan atau denda paling banyak Rp25O.00O,OO (dua ratus lima puluh ribu rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"302","heading":null,"bab":null,"bab_heading":null,"sort_order":2465}', '/akn/id/act/uu/2023/6#pasal-302', 'diubah', NULL, NULL, NULL, NULL);
