INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_288', 'Pasal 288', 'ARTICLE', 'Setiap Orang yang mengoperasikan Kapal pada angkutan sungai dan danau tanpa memenuhi Perizinan Benrsaha untuk Trayek sebagaimana dimaksud dalam Pasal 28 ayat (4) yang menimbulkan kecelakaan Kapal, korban manusia, atau kerugian harta benda dipidana dengan pidana penjara paling lama I (satu) tahun atau pidana denda paling banyak Rp30O.000.O00,00 (tiga ratus juta rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"288","heading":null,"bab":null,"bab_heading":null,"sort_order":2741}', '/akn/id/act/uu/2023/6#pasal-288', 'diubah', NULL, NULL, NULL, NULL);
