INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_62_a24454499', 'Pasal 62', 'ARTICLE', 'Setiap orang yang dengan sengaja menyelenggarakan Rumah Sakit yang tidak memenuhi Perizinan Berusaha sebagaimana dimaksud dalam Pasal 25 ayat (1) yang mengakibatkan timbulnya korban/kerusakan terhadap kesehatan, keselamatan, dan/atau lingkungan dipidana dengan pidana penjara paling lama 2 (dua) tahun dan pidana denda paling banyak Rp7.000.000.000,00 (tujuh miliar rupiah).', NULL, '{"law_id":"uu_2023_6","pasal":"62","heading":null,"bab":null,"bab_heading":null,"sort_order":3095}', '/akn/id/act/uu/2023/6#pasal-62~3', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_5_a24454502', 'Pasal 5', 'ARTICLE', 'Psikotropika hanya dapat diproduksi oleh industri farmasi yang telah memenuhi Perizinan Berusaha dari Pemerintah Pusat.', NULL, '{"law_id":"uu_2023_6","pasal":"5","heading":null,"bab":null,"bab_heading":null,"sort_order":3098}', '/akn/id/act/uu/2023/6#pasal-5~10', 'diubah', NULL, NULL, NULL, NULL);
