INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_19_a24454518', 'Pasal 19', 'ARTICLE', 'Pemerintah Pusat menyampaikan surat persetujuan impor terkait impor Psikotropika kepada pemerintah negara pengekspor Psikotropika.', NULL, '{"law_id":"uu_2023_6","pasal":"19","heading":null,"bab":null,"bab_heading":null,"sort_order":3114}', '/akn/id/act/uu/2023/6#pasal-19~9', 'diubah', NULL, NULL, NULL, NULL);
