INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_88f', 'Pasal 88F', 'ARTICLE', 'Dalam keadaan tertentu Pemerintah dapat menetapkan formula penghitungan Upah minimum yang berbeda dengan formula penghitungan Upah minimum sebagaimana dimaksud dalam Pasal 88D ayat (2).', NULL, '{"law_id":"uu_2023_6","pasal":"88F","heading":null,"bab":null,"bab_heading":null,"sort_order":3714}', '/akn/id/act/uu/2023/6#pasal-88F', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_90a', 'Pasal 90A', 'ARTICLE', 'Upah di atas Upah minimum ditetapkan berdasarkan kesepakatan antara Pengusaha dan Pekerja/Buruh di Perusahaan.', NULL, '{"law_id":"uu_2023_6","pasal":"90A","heading":null,"bab":null,"bab_heading":null,"sort_order":3717}', '/akn/id/act/uu/2023/6#pasal-90A', 'diubah', NULL, NULL, NULL, NULL);
