INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_95_a24455372', 'Pasal 95', 'ARTICLE', '', NULL, '{"law_id":"uu_2023_6","pasal":"95","heading":null,"bab":null,"bab_heading":null,"sort_order":3968}', '/akn/id/act/uu/2023/6#pasal-95~5', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_96_a24455375', 'Pasal 96', 'ARTICLE', 'Pemerintah Pusat dan Pemerintah Daerah sesuai dengan kewenangannya wajib menyediakan layanan bantuan dan pendampingan hukum bagi Usaha Mikro dan Kecil.', NULL, '{"law_id":"uu_2023_6","pasal":"96","heading":null,"bab":null,"bab_heading":null,"sort_order":3971}', '/akn/id/act/uu/2023/6#pasal-96~6', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_97_a24455376', 'Pasal 97', 'ARTICLE', 'Pemerintah Pusat dan Pemerintah Daerah wajib mengalokasikan paling sedikit (empat puluh persen) 4Oo/o produk/jasa Usaha Mikro dan Kecil serta Koperasi dari hasil produksi dalam negeri dalam pengadaan barang/jasa Pemerintah Pusat dan Pemerintah Daerah sesuai dengan ketentuan peraturan perundang-undangan.', NULL, '{"law_id":"uu_2023_6","pasal":"97","heading":null,"bab":null,"bab_heading":null,"sort_order":3972}', '/akn/id/act/uu/2023/6#pasal-97~5', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_98_a24455377', 'Pasal 98', 'ARTICLE', 'Pemerintah Pusat dan Pemerintah Daerah sesuai dengan kewenangannya wajib memberikan pelatihan dan pendampingan pemanfaatan sistem/aplikasi pembukuan/pencatatan keuangan yang memberi kemudahan bagi Usaha Mikro dan Kecil.', NULL, '{"law_id":"uu_2023_6","pasal":"98","heading":null,"bab":null,"bab_heading":null,"sort_order":3973}', '/akn/id/act/uu/2023/6#pasal-98~5', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_99_a24455378', 'Pasal 99', 'ARTICLE', 'Penyelenggaraan inkubasi dilakukan oleh Pemerintah Pusat, Pemerintah Daerah, perguruan tinggi, Dunia Usaha, dan/ atau masyarakat.', NULL, '{"law_id":"uu_2023_6","pasal":"99","heading":null,"bab":null,"bab_heading":null,"sort_order":3974}', '/akn/id/act/uu/2023/6#pasal-99~7', 'diubah', NULL, NULL, NULL, NULL);
