INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_174', 'Pasal 174', 'ARTICLE', 'Dengan berlakunya Peraturan Pemerintah Pengganti Undang-Undang ini, kewenangan menteri, kepala lembaga, atau Pemerintah Daerah yang telah ditetapkan dalam undang-undang untuk menjalankan atau membentuk peraturan perundang-undangan harus dimaknai sebagai pelaksanaan kewenangan Presiden.', NULL, '{"law_id":"uu_2023_6","pasal":"174","heading":null,"bab":null,"bab_heading":null,"sort_order":4717}', '/akn/id/act/uu/2023/6#pasal-174', 'diubah', NULL, NULL, NULL, NULL);
