INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_250_a24456152', 'Pasal 250', 'ARTICLE', 'Perda dan Perkada sebagaimana dimaksud dalam Pasal 249 ayat (1) dan ayat (3) dilarang bertentangan dengan ketentuan peraturan perundang-undangan yang lebih tinggi, asas pembentukan peraturan perundang-undangan yang baik, asas materi muatan peraturan perundang-undangan, dan putusan pengadilan.', NULL, '{"law_id":"uu_2023_6","pasal":"250","heading":null,"bab":null,"bab_heading":null,"sort_order":4748}', '/akn/id/act/uu/2023/6#pasal-250~2', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_251', 'Pasal 251', 'ARTICLE', 'Agar tidak bertentangan dengan ketentuan peraturan perundang-undangan yang lebih tinggi, asas pembentukan peraturan perundang-undangan yang baik, asas materi muatan peraturan perundang-undangan, dan putusan pengadilan, penyusunan Perda dan Perkada berkoordinasi dengan kementerian yang membidangi urusan pemerintahan dalam negeri dan melibatkan ahli dan/atau instansi vertikal di daerah yang menyelenggarakan urusan pemerintahan di bidang pembentukan peraturan perundang-undangan.', NULL, '{"law_id":"uu_2023_6","pasal":"251","heading":null,"bab":null,"bab_heading":null,"sort_order":4750}', '/akn/id/act/uu/2023/6#pasal-251', 'diubah', NULL, NULL, NULL, NULL);
