INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2023_6_pasal_402a', 'Pasal 402A', 'ARTICLE', 'Pembagran urusan pemerintahan konkuren antara Pemerintah Pusat dan Pemerintah Daerah provinsi serta Pemerintah Daerah kabupaten/kota sebagaimana tercantum dalam L,ampiran Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah sebagaimana telah diubah terakhir dengan Undang-Undang Nomor 9 Tahun 2Ol5 tentang Perubahan Kedua atas Undang-Undang Nomor 23 Tahun 2014 tenta ng Pemerintahan Daerah harus dibaca dan dimaknai sesuai dengan ketentuan yang diatur dalam Peraturan Pemerintah Pengganti Undang-Undang ini.', NULL, '{"law_id":"uu_2023_6","pasal":"402A","heading":null,"bab":null,"bab_heading":null,"sort_order":4782}', '/akn/id/act/uu/2023/6#pasal-402A', 'diubah', NULL, NULL, NULL, NULL);
