INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_2', 'Pasal 2', 'ARTICLE', 'Undang-undang ini mengatur penyelesaian sengketa atau beda pendapat antar para pihak dalam suatu hubungan hukum tertentu yang telah mengadakan perjanjian arbitrase yang secara tegas menyatakan bahwa semua sengketa atau beda pendapat yang timbul atau yang mungkin timbul dari hubungan hukum tersebut akan diselesaikan dengan cara arbitrase atau melalui alternatif penyelesaian sengketa.', NULL, '{"law_id":"uu_1999_30","pasal":"2","heading":null,"bab":"I","bab_heading":"KETENTUAN UMUM","sort_order":4}', '/akn/id/act/uu/1999/30#pasal-2', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_3', 'Pasal 3', 'ARTICLE', 'Pengadilan Negeri tidak berwenang untuk mengadili sengketa para pihak yang telah terikat dalam perjanjian arbitrase.', NULL, '{"law_id":"uu_1999_30","pasal":"3","heading":null,"bab":"I","bab_heading":"KETENTUAN UMUM","sort_order":5}', '/akn/id/act/uu/1999/30#pasal-3', 'berlaku', NULL, NULL, NULL, NULL);
