INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_20', 'Pasal 20', 'ARTICLE', 'Dalam hal arbiter atau majelis arbitrase tanpa alasan yang sah tidak memberikan putusan dalam jangka waktu yang telah ditentukan, arbiter dapat dihukum untuk mengganti biaya dan kerugian yang diakibatkan karena kelambatan tersebut kepada para pihak.', NULL, '{"law_id":"uu_1999_30","pasal":"20","heading":null,"bab":null,"bab_heading":null,"sort_order":70}', '/akn/id/act/uu/1999/30#pasal-20', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_21', 'Pasal 21', 'ARTICLE', 'Arbiter atau majelis arbitrase tidak dapat dikenakan tanggung jawab hukum apapun atas segala tindakan yang diambil selama proses persidangan berlangsung untuk menjalankan fungsinya sebagai arbiter atau majelis arbitrase, kecuali dapat dibuktikan adanya itikad tidak baik dari tindakan tersebut.', NULL, '{"law_id":"uu_1999_30","pasal":"21","heading":null,"bab":null,"bab_heading":null,"sort_order":71}', '/akn/id/act/uu/1999/30#pasal-21', 'berlaku', NULL, NULL, NULL, NULL);
