INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_27', 'Pasal 27', 'ARTICLE', 'Semua pemeriksaan sengketa oleh arbiter atau majelis arbitrase dilakukan secara tertutup.', NULL, '{"law_id":"uu_1999_30","pasal":"27","heading":null,"bab":"IV","bab_heading":"ACARA YANG BERLAKU DIHADAPAN MAJELIS ARBITRASE","sort_order":98}', '/akn/id/act/uu/1999/30#pasal-27', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_28', 'Pasal 28', 'ARTICLE', 'Bahasa yang digunakan dalam semua proses arbitrase adalah bahasa Indonesia, kecuali atas persetujuan arbiter atau majelis arbitrase para pihak dapat memilih bahasa lain yang akan digunakan.', NULL, '{"law_id":"uu_1999_30","pasal":"28","heading":null,"bab":"IV","bab_heading":"ACARA YANG BERLAKU DIHADAPAN MAJELIS ARBITRASE","sort_order":99}', '/akn/id/act/uu/1999/30#pasal-28', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_29', 'Pasal 29', 'ARTICLE', '', NULL, '{"law_id":"uu_1999_30","pasal":"29","heading":null,"bab":"IV","bab_heading":"ACARA YANG BERLAKU DIHADAPAN MAJELIS ARBITRASE","sort_order":100}', '/akn/id/act/uu/1999/30#pasal-29', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_30', 'Pasal 30', 'ARTICLE', 'Pihak ketiga di luar perjanjian arbitrase dapat turut serta dan menggabungkan diri dalam proses penyelesaian sengketa melalui arbitrase, apabila terdapat unsur kepentingan yang terkait dan keturutsertaannya disepakati oleh para pihak yang bersengketa serta disetujui oleh arbiter atau majelis arbitrase yang memeriksa sengketa yang bersangkutan.', NULL, '{"law_id":"uu_1999_30","pasal":"30","heading":null,"bab":"IV","bab_heading":"ACARA YANG BERLAKU DIHADAPAN MAJELIS ARBITRASE","sort_order":103}', '/akn/id/act/uu/1999/30#pasal-30', 'berlaku', NULL, NULL, NULL, NULL);
