INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_35', 'Pasal 35', 'ARTICLE', 'Arbiter atau majelis arbitrase dapat memerintahkan agar setiap dokumen atau bukti disertai dengan terjemahan ke dalam bahasa yang ditetapkan oleh arbiter atau majelis arbitrase.', NULL, '{"law_id":"uu_1999_30","pasal":"35","heading":null,"bab":"IV","bab_heading":"ACARA YANG BERLAKU DIHADAPAN MAJELIS ARBITRASE","sort_order":115}', '/akn/id/act/uu/1999/30#pasal-35', 'berlaku', NULL, NULL, NULL, NULL);
