INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_39', 'Pasal 39', 'ARTICLE', 'Setelah menerima surat tuntutan dari pemohon, arbiter atau ketua majelis arbitrase menyampaikan satu salinan tuntutan tersebut kepada termohon dengan disertai perintah bahwa termohon harus menanggapi dan memberikan jawabannya secara tertulis dalam waktu paling lama 14 ( empat belas ) hari sejak diterimanya salinan tuntutan tersebut oleh termohon.', NULL, '{"law_id":"uu_1999_30","pasal":"39","heading":null,"bab":"IV","bab_heading":"ACARA YANG BERLAKU DIHADAPAN MAJELIS ARBITRASE","sort_order":127}', '/akn/id/act/uu/1999/30#pasal-39', 'berlaku', NULL, NULL, NULL, NULL);
