INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_41', 'Pasal 41', 'ARTICLE', 'Dalam hal termohon setelah lewat 14 (empat belas) hari sebagaimana dimaksud dalam Pasal 39 tidak menyampaikan jawabannya, termohon akan dipanggil dengan ketentuan sebagaimana dimaksud dalam Pasal 40 ayat (2) .', NULL, '{"law_id":"uu_1999_30","pasal":"41","heading":null,"bab":"IV","bab_heading":"ACARA YANG BERLAKU DIHADAPAN MAJELIS ARBITRASE","sort_order":131}', '/akn/id/act/uu/1999/30#pasal-41', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_42', 'Pasal 42', 'ARTICLE', '', NULL, '{"law_id":"uu_1999_30","pasal":"42","heading":null,"bab":"IV","bab_heading":"ACARA YANG BERLAKU DIHADAPAN MAJELIS ARBITRASE","sort_order":132}', '/akn/id/act/uu/1999/30#pasal-42', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_43', 'Pasal 43', 'ARTICLE', 'Apabila pada hari yang ditentukan sebagaimana dimaksud dalam Pasal 40 ayat (2) pemohon tanpa suatu alasan yang sah tidak datang menghadap, sedangkan telah dipanggil secara patut, surat tuntutannya dinyatakan gugur dan tugas arbiter atau majelis arbitrase dianggap selesai.', NULL, '{"law_id":"uu_1999_30","pasal":"43","heading":null,"bab":"IV","bab_heading":"ACARA YANG BERLAKU DIHADAPAN MAJELIS ARBITRASE","sort_order":135}', '/akn/id/act/uu/1999/30#pasal-43', 'berlaku', NULL, NULL, NULL, NULL);
