INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_51', 'Pasal 51', 'ARTICLE', 'Terhadap kegiatan dalam pemeriksaan dan sidang arbitrase dibuat berita acara pemeriksaan oleh sekretaris.', NULL, '{"law_id":"uu_1999_30","pasal":"51","heading":null,"bab":null,"bab_heading":null,"sort_order":162}', '/akn/id/act/uu/1999/30#pasal-51', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_52', 'Pasal 52', 'ARTICLE', 'Para pihak dalam suatu perjanjian berhak untuk memohon pendapat yang mengikat dari lembaga arbitrase atas hubungan hukum tertentu dari suatu perjanjian.', NULL, '{"law_id":"uu_1999_30","pasal":"52","heading":null,"bab":"V","bab_heading":"PENDAPAT DAN PUTUSAN ARBITRASE","sort_order":164}', '/akn/id/act/uu/1999/30#pasal-52', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_53', 'Pasal 53', 'ARTICLE', 'Terhadap pendapat yang mengikat sebagaimana dimaksud dalam Pasal 52 tidak dapat dilakukan perlawanan melalui upaya hukum apapun.', NULL, '{"law_id":"uu_1999_30","pasal":"53","heading":null,"bab":"V","bab_heading":"PENDAPAT DAN PUTUSAN ARBITRASE","sort_order":165}', '/akn/id/act/uu/1999/30#pasal-53', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_54', 'Pasal 54', 'ARTICLE', '', NULL, '{"law_id":"uu_1999_30","pasal":"54","heading":null,"bab":"V","bab_heading":"PENDAPAT DAN PUTUSAN ARBITRASE","sort_order":166}', '/akn/id/act/uu/1999/30#pasal-54', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_55', 'Pasal 55', 'ARTICLE', 'Apabila pemeriksaan sengketa telah selesai, pemeriksaan segera ditutup dan ditetapkan hari sidang untuk mengucapkan putusan arbitrase.', NULL, '{"law_id":"uu_1999_30","pasal":"55","heading":null,"bab":"V","bab_heading":"PENDAPAT DAN PUTUSAN ARBITRASE","sort_order":171}', '/akn/id/act/uu/1999/30#pasal-55', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_56', 'Pasal 56', 'ARTICLE', '', NULL, '{"law_id":"uu_1999_30","pasal":"56","heading":null,"bab":"V","bab_heading":"PENDAPAT DAN PUTUSAN ARBITRASE","sort_order":172}', '/akn/id/act/uu/1999/30#pasal-56', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_57', 'Pasal 57', 'ARTICLE', 'Putusan diucapkan dalam waktu paling lama 30 (tiga puluh) hari setelah pemeriksaan ditutup.', NULL, '{"law_id":"uu_1999_30","pasal":"57","heading":null,"bab":"V","bab_heading":"PENDAPAT DAN PUTUSAN ARBITRASE","sort_order":175}', '/akn/id/act/uu/1999/30#pasal-57', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_58', 'Pasal 58', 'ARTICLE', 'Dalam waktu paling lama 14 (empat belas) hari setelah putusan diterima, para pihak dapat mengajukan permohonan kepada arbiter atau majelis arbitrase untuk melakukan koreksi terhadap kekeliruan administratif dan atau menambah atau mengurangi sesuatu tuntutan putusan.', NULL, '{"law_id":"uu_1999_30","pasal":"58","heading":null,"bab":"V","bab_heading":"PENDAPAT DAN PUTUSAN ARBITRASE","sort_order":176}', '/akn/id/act/uu/1999/30#pasal-58', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_59', 'Pasal 59', 'ARTICLE', '', NULL, '{"law_id":"uu_1999_30","pasal":"59","heading":null,"bab":"VI","bab_heading":"PELAKSANAAN PUTUSAN ARBITRASE","sort_order":178}', '/akn/id/act/uu/1999/30#pasal-59', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_60', 'Pasal 60', 'ARTICLE', 'Putusan arbitrase bersifat final dan mempunyai kekuatan hukum tetap dan mengikat para pihak .', NULL, '{"law_id":"uu_1999_30","pasal":"60","heading":null,"bab":"VI","bab_heading":"PELAKSANAAN PUTUSAN ARBITRASE","sort_order":184}', '/akn/id/act/uu/1999/30#pasal-60', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_61', 'Pasal 61', 'ARTICLE', 'Dalam hal para pihak tidak melaksanakan putusan arbitrase secara sukarela, putusan dilaksanakan berdasarkan perintah Ketua Pengadilan Negeri atas permohonan salah satu pihak yang bersengketa.', NULL, '{"law_id":"uu_1999_30","pasal":"61","heading":null,"bab":"VI","bab_heading":"PELAKSANAAN PUTUSAN ARBITRASE","sort_order":185}', '/akn/id/act/uu/1999/30#pasal-61', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_62', 'Pasal 62', 'ARTICLE', '', NULL, '{"law_id":"uu_1999_30","pasal":"62","heading":null,"bab":"VI","bab_heading":"PELAKSANAAN PUTUSAN ARBITRASE","sort_order":186}', '/akn/id/act/uu/1999/30#pasal-62', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_63', 'Pasal 63', 'ARTICLE', 'Perintah Ketua Pengadilan Negeri ditulis pada lembar asli dan salinan otentik putusan arbitrase yang dikeluarkan.', NULL, '{"law_id":"uu_1999_30","pasal":"63","heading":null,"bab":"VI","bab_heading":"PELAKSANAAN PUTUSAN ARBITRASE","sort_order":191}', '/akn/id/act/uu/1999/30#pasal-63', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_64', 'Pasal 64', 'ARTICLE', 'Putusan arbitrase yang telah dibubuhi perintah Ketua Pengadilan Negeri, dilaksanakan sesuai ketentuan pelaksanaan putusan dalam perkara perdata yang putusannya telah mempunyai kekuatan hukum tetap.', NULL, '{"law_id":"uu_1999_30","pasal":"64","heading":null,"bab":"VI","bab_heading":"PELAKSANAAN PUTUSAN ARBITRASE","sort_order":192}', '/akn/id/act/uu/1999/30#pasal-64', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_65', 'Pasal 65', 'ARTICLE', 'Yang berwenang menangani masalah pengakuan dan pelaksanaan Putusan Arbitrase Internasional adalah Pengadilan Negeri Jakarta Pusat.', NULL, '{"law_id":"uu_1999_30","pasal":"65","heading":null,"bab":null,"bab_heading":null,"sort_order":194}', '/akn/id/act/uu/1999/30#pasal-65', 'berlaku', NULL, NULL, NULL, NULL);
