INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_71', 'Pasal 71', 'ARTICLE', 'Permohonan pembatalan putusan arbitrase harus diajukan secara tertulis dalam waktu paling lama 30 (tiga puluh) hari terhitung sejak hari penyerahan dan pendaftaran putusan arbitrase kepada Panitera Pengadilan Negeri.', NULL, '{"law_id":"uu_1999_30","pasal":"71","heading":null,"bab":"VII","bab_heading":"PEMBATALAN PUTUSAN ARBITRASE","sort_order":210}', '/akn/id/act/uu/1999/30#pasal-71', 'berlaku', NULL, NULL, NULL, NULL);
