INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_77', 'Pasal 77', 'ARTICLE', '', NULL, '{"law_id":"uu_1999_30","pasal":"77","heading":null,"bab":"IX","bab_heading":"BIAYA ARBITRASE","sort_order":230}', '/akn/id/act/uu/1999/30#pasal-77', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_78', 'Pasal 78', 'ARTICLE', 'Sengketa yang pada saat Undang-undang ini mulai berlaku sudah diajukan kepada arbiter atau lembaga arbitrase tetapi belum dilakukan pemeriksaan, proses penyelesaiannya dilakukan berdasarkan Undang-undang ini.', NULL, '{"law_id":"uu_1999_30","pasal":"78","heading":null,"bab":"X","bab_heading":"KETENTUAN PERALIHAN","sort_order":234}', '/akn/id/act/uu/1999/30#pasal-78', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_79', 'Pasal 79', 'ARTICLE', 'Sengketa yang pada saat Undang-undang ini mulai berlaku sudah diperiksa tetapi belum diputus, tetap diperiksa dan diputus berdasarkan ketentuan peraturan perundang-undangan yang lama.', NULL, '{"law_id":"uu_1999_30","pasal":"79","heading":null,"bab":"X","bab_heading":"KETENTUAN PERALIHAN","sort_order":235}', '/akn/id/act/uu/1999/30#pasal-79', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_80', 'Pasal 80', 'ARTICLE', 'Sengketa yang pada saat Undang-undang ini mulai berlaku sudah diputus dan putusannya telah memperoleh kekuatan hukum tetap, pelaksanaannya dilakukan berdasarkan Undang-undang ini.', NULL, '{"law_id":"uu_1999_30","pasal":"80","heading":null,"bab":"X","bab_heading":"KETENTUAN PERALIHAN","sort_order":236}', '/akn/id/act/uu/1999/30#pasal-80', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_30_pasal_81', 'Pasal 81', 'ARTICLE', 'Pada saat Undang-undang ini mulai berlaku, ketentuan mengenai arbitrase sebagaimana dimaksud dalam Pasal 615 sampai dengan Pasal 651 Reglemen Acara Perdata ( Reglement op de Rechtsvordering, Staatsblad 1847:52) dan Pasal 377 Reglemen Indonesia Yang Diperbaharui ( Het Herziene Indonesisch Reglement, Staatsblad 1941:44 ) dan Pasal 705 Reglemen Acara Untuk Daerah Luar Jawa dan Madura ( Rechtsreglement Buitengewesten, Staatsblad 1927:227 ), dinyatakan tidak berlaku.', NULL, '{"law_id":"uu_1999_30","pasal":"81","heading":null,"bab":"XI","bab_heading":"KETENTUAN PENUTUP","sort_order":238}', '/akn/id/act/uu/1999/30#pasal-81', 'berlaku', NULL, NULL, NULL, NULL);
