INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_48', 'Pasal 48', 'ARTICLE', 'Pemberi kerja yang mempekerjakan tenaga kerja asing wajib memulangkan tenaga kerja asing ke negara asalnya setelah hubungan kerjanya berakhir.', NULL, '{"law_id":"uu_2003_13","pasal":"48","heading":null,"bab":"VIII","bab_heading":"PENGGUNAAN TENAGA KERJA ASING","sort_order":155}', '/akn/id/act/uu/2003/13#pasal-48', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_49', 'Pasal 49', 'ARTICLE', 'Ketentuan mengenai penggunaan tenaga kerja asing serta pelaksanaan pendidikan dan pelatihan tenaga kerja pendamping diatur dengan Keputusan Presiden.', NULL, '{"law_id":"uu_2003_13","pasal":"49","heading":null,"bab":"VIII","bab_heading":"PENGGUNAAN TENAGA KERJA ASING","sort_order":156}', '/akn/id/act/uu/2003/13#pasal-49', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_50', 'Pasal 50', 'ARTICLE', 'Hubungan kerja terjadi karena adanya perjanjian kerja antara pengusaha dan pekerja/buruh.', NULL, '{"law_id":"uu_2003_13","pasal":"50","heading":null,"bab":"IX","bab_heading":"HUBUNGAN KERJA","sort_order":158}', '/akn/id/act/uu/2003/13#pasal-50', 'diubah', NULL, NULL, NULL, NULL);
