INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_53', 'Pasal 53', 'ARTICLE', 'Segala hal dan/atau biaya yang diperlukan bagi pelaksanaan pembuatan perjanjian kerja dilaksanakan oleh dan menjadi tanggung jawab pengusaha.', NULL, '{"law_id":"uu_2003_13","pasal":"53","heading":null,"bab":"IX","bab_heading":"HUBUNGAN KERJA","sort_order":166}', '/akn/id/act/uu/2003/13#pasal-53', 'diubah', NULL, NULL, NULL, NULL);
