INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_62', 'Pasal 62', 'ARTICLE', 'Apabila salah satu pihak mengakhiri hubungan kerja sebelum berakhirnya jangka waktu yang ditetapkan dalam perjanjian kerja waktu tertentu, atau berakhirnya hubungan kerja bukan karena ketentuan sebagaimana dimaksud dalam Pasal 61 ayat (1), pihak yang mengakhiri hubungan kerja diwajibkan membayar ganti rugi kepada pihak lainnya sebesar upah pekerja/buruh sampai batas waktu berakhirnya jangka waktu perjanjian kerja.', NULL, '{"law_id":"uu_2003_13","pasal":"62","heading":null,"bab":"IX","bab_heading":"HUBUNGAN KERJA","sort_order":200}', '/akn/id/act/uu/2003/13#pasal-62', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_63', 'Pasal 63', 'ARTICLE', '', NULL, '{"law_id":"uu_2003_13","pasal":"63","heading":null,"bab":"IX","bab_heading":"HUBUNGAN KERJA","sort_order":201}', '/akn/id/act/uu/2003/13#pasal-63', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_64', 'Pasal 64', 'ARTICLE', 'Perusahaan dapat menyerahkan sebagian pelaksanaan pekerjaan kepada perusahaan lainnya melalui perjanjian pemborongan pekerjaan atau penyedia-an jasa pekerja/buruh yang dibuat secara tertulis.', NULL, '{"law_id":"uu_2003_13","pasal":"64","heading":null,"bab":"IX","bab_heading":"HUBUNGAN KERJA","sort_order":204}', '/akn/id/act/uu/2003/13#pasal-64', 'diubah', NULL, NULL, NULL, NULL);
