INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_72', 'Pasal 72', 'ARTICLE', 'Dalam hal anak dipekerjakan bersama-sama dengan pekerja/buruh dewasa, maka tempat kerja anak harus dipisahkan dari tempat kerja pekerja/buruh dewasa.', NULL, '{"law_id":"uu_2003_13","pasal":"72","heading":null,"bab":null,"bab_heading":null,"sort_order":240}', '/akn/id/act/uu/2003/13#pasal-72', 'diubah', NULL, NULL, NULL, NULL);
