INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_94', 'Pasal 94', 'ARTICLE', 'Dalam hal komponen upah terdiri dari upah pokok dan tunjangan tetap maka besarnya upah pokok sedikit-dikitnya 75 % (tujuh puluh lima perseratus) dari jumlah upah pokok dan tunjangan tetap.', NULL, '{"law_id":"uu_2003_13","pasal":"94","heading":null,"bab":null,"bab_heading":null,"sort_order":324}', '/akn/id/act/uu/2003/13#pasal-94', 'diubah', NULL, NULL, NULL, NULL);
