INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_96', 'Pasal 96', 'ARTICLE', 'Tuntutan pembayaran upah pekerja/buruh dan segala pembayaran yang timbul dari hubungan kerja menjadi kadaluwarsa setelah melampaui jangka waktu 2 (dua) tahun sejak timbulnya hak.', NULL, '{"law_id":"uu_2003_13","pasal":"96","heading":null,"bab":null,"bab_heading":null,"sort_order":330}', '/akn/id/act/uu/2003/13#pasal-96', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_97', 'Pasal 97', 'ARTICLE', 'Ketentuan mengenai penghasilan yang layak, kebijakan pengupahan, kebutuhan hidup layak, dan perlindungan pengupahan sebagaimana dimaksud dalam Pasal 88, penetapan upah minimum sebagaimana dimaksud dalam Pasal 89, dan pengenaan denda sebagaimana dimaksud dalam Pasal 95 ayat (1), ayat (2) dan ayat (3) diatur dengan Peraturan Pemerintah.', NULL, '{"law_id":"uu_2003_13","pasal":"97","heading":null,"bab":null,"bab_heading":null,"sort_order":331}', '/akn/id/act/uu/2003/13#pasal-97', 'diubah', NULL, NULL, NULL, NULL);
