INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_114', 'Pasal 114', 'ARTICLE', 'Pengusaha wajib memberitahukan dan menjelaskan isi serta memberikan naskah peraturan perusahaan atau perubahannya kepada pekerja/buruh.', NULL, '{"law_id":"uu_2003_13","pasal":"114","heading":null,"bab":null,"bab_heading":null,"sort_order":401}', '/akn/id/act/uu/2003/13#pasal-114', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_115', 'Pasal 115', 'ARTICLE', 'Ketentuan mengenai tata cara pembuatan dan pengesahan peraturan perusahaan diatur dengan Keputusan Menteri.', NULL, '{"law_id":"uu_2003_13","pasal":"115","heading":null,"bab":null,"bab_heading":null,"sort_order":402}', '/akn/id/act/uu/2003/13#pasal-115', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_116', 'Pasal 116', 'ARTICLE', '', NULL, '{"law_id":"uu_2003_13","pasal":"116","heading":null,"bab":null,"bab_heading":null,"sort_order":404}', '/akn/id/act/uu/2003/13#pasal-116', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_117', 'Pasal 117', 'ARTICLE', 'Dalam hal musyawarah sebagaimana dimaksud dalam Pasal 116 ayat (2) tidak mencapai kesepakatan, maka penyelesaiannya dilakukan melalui prosedur penyelesaian perselisihan hubungan industrial.', NULL, '{"law_id":"uu_2003_13","pasal":"117","heading":null,"bab":null,"bab_heading":null,"sort_order":409}', '/akn/id/act/uu/2003/13#pasal-117', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_118', 'Pasal 118', 'ARTICLE', 'Dalam 1 (satu) perusahaan hanya dapat dibuat 1 (satu) perjanjian kerja bersama yang berlaku bagi seluruh pekerja/buruh di perusahaan.', NULL, '{"law_id":"uu_2003_13","pasal":"118","heading":null,"bab":null,"bab_heading":null,"sort_order":410}', '/akn/id/act/uu/2003/13#pasal-118', 'diubah', NULL, NULL, NULL, NULL);
