INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_120', 'Pasal 120', 'ARTICLE', '', NULL, '{"law_id":"uu_2003_13","pasal":"120","heading":null,"bab":null,"bab_heading":null,"sort_order":415}', '/akn/id/act/uu/2003/13#pasal-120', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_121', 'Pasal 121', 'ARTICLE', 'Keanggotaan serikat pekerja/serikat buruh sebagaimana dimaksud dalam Pasal 119 dan Pasal 120 dibuktikan dengan kartu tanda anggota.', NULL, '{"law_id":"uu_2003_13","pasal":"121","heading":null,"bab":null,"bab_heading":null,"sort_order":419}', '/akn/id/act/uu/2003/13#pasal-121', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_122', 'Pasal 122', 'ARTICLE', 'Pemungutan suara sebagaimana dimaksud dalam Pasal 119 ayat (2) diselenggarakan oleh panitia yang terdiri dari wakil-wakil pekerja/ buruh dan pengurus serikat pekerja/serikat buruh yang disaksikan oleh pihak pejabat yang bertanggung jawab di bidang ketenagakerjaan dan pengusaha.', NULL, '{"law_id":"uu_2003_13","pasal":"122","heading":null,"bab":null,"bab_heading":null,"sort_order":420}', '/akn/id/act/uu/2003/13#pasal-122', 'diubah', NULL, NULL, NULL, NULL);
