INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_125', 'Pasal 125', 'ARTICLE', 'Dalam hal kedua belah pihak sepakat mengadakan perubahan perjanjian kerja bersama, maka perubahan tersebut merupakan bagian yang tidak terpisahkan dari perjanjian kerja bersama yang sedang berlaku.', NULL, '{"law_id":"uu_2003_13","pasal":"125","heading":null,"bab":null,"bab_heading":null,"sort_order":430}', '/akn/id/act/uu/2003/13#pasal-125', 'diubah', NULL, NULL, NULL, NULL);
