INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_128', 'Pasal 128', 'ARTICLE', 'Dalam hal perjanjian kerja tidak memuat aturan-aturan yang diatur dalam perjanjian kerja bersama maka yang berlaku adalah aturan-aturan dalam perjanjian kerja bersama.', NULL, '{"law_id":"uu_2003_13","pasal":"128","heading":null,"bab":null,"bab_heading":null,"sort_order":438}', '/akn/id/act/uu/2003/13#pasal-128', 'diubah', NULL, NULL, NULL, NULL);
