INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_133', 'Pasal 133', 'ARTICLE', 'Ketentuan mengenai persyaratan serta tata cara pembuatan, perpanjangan, perubahan, dan pendaftaran perjanjian kerja bersama diatur dengan Keputusan Menteri.', NULL, '{"law_id":"uu_2003_13","pasal":"133","heading":null,"bab":null,"bab_heading":null,"sort_order":453}', '/akn/id/act/uu/2003/13#pasal-133', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_134', 'Pasal 134', 'ARTICLE', 'Dalam mewujudkan pelaksanaan hak dan kewajiban pekerja/buruh dan pengusaha, pemerintah wajib melaksanakan pengawasan dan penegakan peraturan perundang-undangan ketenagakerjaan.', NULL, '{"law_id":"uu_2003_13","pasal":"134","heading":null,"bab":null,"bab_heading":null,"sort_order":454}', '/akn/id/act/uu/2003/13#pasal-134', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_135', 'Pasal 135', 'ARTICLE', 'Pelaksanaan peraturan perundang-undangan ketenagakerjaan dalam mewujudkan hubungan industrial merupakan tanggung jawab pekerja/buruh, pengusaha, dan pemerintah.', NULL, '{"law_id":"uu_2003_13","pasal":"135","heading":null,"bab":null,"bab_heading":null,"sort_order":455}', '/akn/id/act/uu/2003/13#pasal-135', 'diubah', NULL, NULL, NULL, NULL);
