INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_137', 'Pasal 137', 'ARTICLE', 'Mogok kerja sebagai hak dasar pekerja/buruh dan serikat pekerja/serikat buruh dilakukan secara sah, tertib, dan damai sebagai akibat gagalnya perundingan.', NULL, '{"law_id":"uu_2003_13","pasal":"137","heading":null,"bab":null,"bab_heading":null,"sort_order":462}', '/akn/id/act/uu/2003/13#pasal-137', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_138', 'Pasal 138', 'ARTICLE', '', NULL, '{"law_id":"uu_2003_13","pasal":"138","heading":null,"bab":null,"bab_heading":null,"sort_order":463}', '/akn/id/act/uu/2003/13#pasal-138', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_139', 'Pasal 139', 'ARTICLE', 'Pelaksanaan mogok kerja bagi pekerja/buruh yang bekerja pada perusahaan yang melayani kepentingan umum dan/atau perusahaan yang jenis kegiatan-nya membahayakan keselamatan jiwa manusia diatur sedemikian rupa sehingga tidak mengganggu kepentingan umum dan/atau membahayakan keselamatan orang lain.', NULL, '{"law_id":"uu_2003_13","pasal":"139","heading":null,"bab":null,"bab_heading":null,"sort_order":466}', '/akn/id/act/uu/2003/13#pasal-139', 'diubah', NULL, NULL, NULL, NULL);
