INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_145', 'Pasal 145', 'ARTICLE', 'Dalam hal pekerja/buruh yang melakukan mogok kerja secara sah dalam melakukan tuntutan hak normatif yang sungguh-sungguh dilanggar oleh pengusaha, pekerja/buruh berhak mendapatkan upah.', NULL, '{"law_id":"uu_2003_13","pasal":"145","heading":null,"bab":null,"bab_heading":null,"sort_order":486}', '/akn/id/act/uu/2003/13#pasal-145', 'diubah', NULL, NULL, NULL, NULL);
