INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_147', 'Pasal 147', 'ARTICLE', 'Penutupan perusahaan (lock out) dilarang dilakukan pada perusahaan-perusahaan yang melayani kepentingan umum dan/atau jenis kegiatan yang membahayakan keselamatan jiwa manusia, meliputi rumah sakit, pelayanan jaringan air bersih, pusat pengendali telekomunikasi, pusat penyedia tenaga listrik, pengolahan minyak dan gas bumi, serta kereta api.', NULL, '{"law_id":"uu_2003_13","pasal":"147","heading":null,"bab":null,"bab_heading":null,"sort_order":492}', '/akn/id/act/uu/2003/13#pasal-147', 'diubah', NULL, NULL, NULL, NULL);
