INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_150', 'Pasal 150', 'ARTICLE', 'Ketentuan mengenai pemutusan hubungan kerja dalam undang-undang ini meliputi pemutusan hubungan kerja yang terjadi di badan usaha yang berbadan hukum atau tidak, milik orang perseorangan, milik persekutuan atau milik badan hukum, baik milik swasta maupun milik negara, maupun usaha-usaha sosial dan usaha-usaha lain yang mempunyai pengurus dan mempekerjakan orang lain dengan membayar upah atau imbalan dalam bentuk lain.', NULL, '{"law_id":"uu_2003_13","pasal":"150","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":505}', '/akn/id/act/uu/2003/13#pasal-150', 'diubah', NULL, NULL, NULL, NULL);
