INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_159', 'Pasal 159', 'ARTICLE', 'Apabila pekerja/buruh tidak menerima pemutusan hubungan kerja sebagaimana dimaksud dalam Pasal 158 ayat (1), pekerja/buruh yang bersangkutan dapat mengajukan gugatan ke lembaga penyelesaian perselisihan hubungan industrial.', NULL, '{"law_id":"uu_2003_13","pasal":"159","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":537}', '/akn/id/act/uu/2003/13#pasal-159', 'diubah', NULL, NULL, NULL, NULL);
