INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_164', 'Pasal 164', 'ARTICLE', '', NULL, '{"law_id":"uu_2003_13","pasal":"164","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":558}', '/akn/id/act/uu/2003/13#pasal-164', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_165', 'Pasal 165', 'ARTICLE', 'Pengusaha dapat melakukan pemutusan hubungan kerja terhadap pekerja/ buruh karena perusahaan pailit, dengan ketentuan pekerja/buruh berhak atas uang pesangon sebesar 1 (satu) kali ketentuan Pasal 156 ayat (2), uang penghargaan masa kerja sebesar 1 (satu) kali ketentuan Pasal 156 ayat (3) dan uang penggantian hak sesuai ketentuan Pasal 156 ayat (4).', NULL, '{"law_id":"uu_2003_13","pasal":"165","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":562}', '/akn/id/act/uu/2003/13#pasal-165', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_166', 'Pasal 166', 'ARTICLE', 'Dalam hal hubungan kerja berakhir karena pekerja/buruh meninggal dunia, kepada ahli warisnya diberikan sejumlah uang yang besar perhitungannya sama dengan perhitungan 2 (dua) kali uang pesangon sesuai ketentuan Pasal 156 ayat (2), 1 (satu) kali uang penghargaan masa kerja sesuai ketentuan Pasal 156 ayat (3), dan uang penggantian hak sesuai ketentuan Pasal 156 ayat (4).', NULL, '{"law_id":"uu_2003_13","pasal":"166","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":563}', '/akn/id/act/uu/2003/13#pasal-166', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_167', 'Pasal 167', 'ARTICLE', '', NULL, '{"law_id":"uu_2003_13","pasal":"167","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":564}', '/akn/id/act/uu/2003/13#pasal-167', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_168', 'Pasal 168', 'ARTICLE', '', NULL, '{"law_id":"uu_2003_13","pasal":"168","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":571}', '/akn/id/act/uu/2003/13#pasal-168', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_169', 'Pasal 169', 'ARTICLE', '', NULL, '{"law_id":"uu_2003_13","pasal":"169","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":575}', '/akn/id/act/uu/2003/13#pasal-169', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_170', 'Pasal 170', 'ARTICLE', 'Pemutusan hubungan kerja yang dilakukan tidak memenuhi keten-tuan Pasal 151 ayat (3) dan Pasal 168, kecuali Pasal 158 ayat (1), Pasal 160 ayat (3), Pasal 162, dan Pasal 169 batal demi hukum dan pengusaha wajib mempekerjakan pekerja/buruh yang bersangkutan serta membayar seluruh upah dan hak yang seharusnya diterima.', NULL, '{"law_id":"uu_2003_13","pasal":"170","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":579}', '/akn/id/act/uu/2003/13#pasal-170', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_171', 'Pasal 171', 'ARTICLE', 'Pekerja/buruh yang mengalami pemutusan hubungan kerja tanpa penetapan lembaga penyelesaian perselisihan hubungan industrial yang berwenang sebagaimana dimaksud dalam Pasal 158 ayat (1), Pasal 160 ayat (3), dan Pasal 162, dan pekerja/buruh yang bersangkutan tidak dapat menerima pemutusan hubungan kerja tersebut, maka pekerja/buruh dapat mengajukan gugatan ke lembaga penyelesaian perselisihan hubungan industrial dalam waktu paling lama 1 (satu) tahun sejak tanggal dilakukan pemutusan hubungan kerjanya.', NULL, '{"law_id":"uu_2003_13","pasal":"171","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":580}', '/akn/id/act/uu/2003/13#pasal-171', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_172', 'Pasal 172', 'ARTICLE', 'Pekerja/buruh yang mengalami sakit berkepanjangan, mengalami cacat akibat kecelakaan kerja dan tidak dapat melakukan pekerjaannya setelah melampaui batas 12 (dua belas) bulan dapat mengajukan pemutusan hubungan kerja dan diberikan uang pesangon 2 (dua) kali ketentuan Pasal 156 ayat (2), uang penghargaan masa kerja 2 (dua) kali ketentuan Pasal 156 ayat (3), dan uang pengganti hak 1 (satu) kali ketentuan Pasal 156 ayat (4).', NULL, '{"law_id":"uu_2003_13","pasal":"172","heading":null,"bab":"XII","bab_heading":"PEMUTUSAN HUBUNGAN KERJA","sort_order":581}', '/akn/id/act/uu/2003/13#pasal-172', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_173', 'Pasal 173', 'ARTICLE', CAST(x'' AS TEXT), NULL, '{"law_id":"uu_2003_13","pasal":"173","heading":null,"bab":"XIII","bab_heading":"PEMBINAAN","sort_order":583}', '/akn/id/act/uu/2003/13#pasal-173', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_174', 'Pasal 174', 'ARTICLE', 'Dalam rangka pembinaan ketenagakerjaan, pemerintah, organisasi pengusaha, serikat pekerja/serikat buruh dan organisasi profesi terkait dapat melakukan kerja sama internasional di bidang ketenagakerjaan sesuai dengan peraturan perundang-undangan yang berlaku.', NULL, '{"law_id":"uu_2003_13","pasal":"174","heading":null,"bab":"XIII","bab_heading":"PEMBINAAN","sort_order":584}', '/akn/id/act/uu/2003/13#pasal-174', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_175', 'Pasal 175', 'ARTICLE', '', NULL, '{"law_id":"uu_2003_13","pasal":"175","heading":null,"bab":"XIII","bab_heading":"PEMBINAAN","sort_order":585}', '/akn/id/act/uu/2003/13#pasal-175', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_176', 'Pasal 176', 'ARTICLE', 'Pengawasan ketenagakerjaan dilakukan oleh pegawai pengawas ketenaga-kerjaan yang mempunyai kompetensi dan independen guna menjamin pelaksanaan peraturan perundang-undangan ketenagakerjaan.', NULL, '{"law_id":"uu_2003_13","pasal":"176","heading":null,"bab":"XIV","bab_heading":"PENGAWASAN","sort_order":589}', '/akn/id/act/uu/2003/13#pasal-176', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2003_13_pasal_177', 'Pasal 177', 'ARTICLE', 'Pegawai pengawas ketenagakerjaan sebagaimana dimaksud dalam Pasal 176 ditetapkan oleh Menteri atau pejabat yang ditunjuk.', NULL, '{"law_id":"uu_2003_13","pasal":"177","heading":null,"bab":"XIV","bab_heading":"PENGAWASAN","sort_order":590}', '/akn/id/act/uu/2003/13#pasal-177', 'diubah', NULL, NULL, NULL, NULL);
