INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2004_2_pasal_54', 'Pasal 54', 'ARTICLE', 'Arbiter atau majelis arbiter tid ak dapat dikenakan tanggung jawab hukum apapun atas segala tindakan yang diambil selama proses persidangan berlangsung untuk menjalankan fungsinya sebagai arbiter atau majelis arbiter, kecuali dapat dibuktikan adanya itikad tidak baik dari tindakan tersebut.', NULL, '{"law_id":"uu_2004_2","pasal":"54","heading":null,"bab":null,"bab_heading":null,"sort_order":171}', '/akn/id/act/uu/2004/2#pasal-54', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2004_2_pasal_55', 'Pasal 55', 'ARTICLE', 'Pengadilan Hubungan Industrial merupakan pengadilan khusus yang berada pada lingkungan peradilan umum.', NULL, '{"law_id":"uu_2004_2","pasal":"55","heading":null,"bab":null,"bab_heading":null,"sort_order":174}', '/akn/id/act/uu/2004/2#pasal-55', 'berlaku', NULL, NULL, NULL, NULL);
