INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2004_2_pasal_57', 'Pasal 57', 'ARTICLE', 'Hukum acara yang berlaku pada Pengadilan Hubungan Industrial adalah Hukum Acara Perdata yang berlaku pada Pengadilan dalam lingkungan Pe radilan Umum, kecuali yang diatur secara khusus dalam undang-undang ini.', NULL, '{"law_id":"uu_2004_2","pasal":"57","heading":null,"bab":null,"bab_heading":null,"sort_order":176}', '/akn/id/act/uu/2004/2#pasal-57', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2004_2_pasal_58', 'Pasal 58', 'ARTICLE', 'Dalam proses beracara di Pengadila n Hubungan Industrial, pihak-pihak yang berperkara tidak dikenakan biaya termasuk biaya eksekusi yang nilai gugatannya di bawah Rp 150.000.000,00 (seratus lima puluh juta rupiah).', NULL, '{"law_id":"uu_2004_2","pasal":"58","heading":null,"bab":null,"bab_heading":null,"sort_order":177}', '/akn/id/act/uu/2004/2#pasal-58', 'berlaku', NULL, NULL, NULL, NULL);
