INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2004_2_pasal_103', 'Pasal 103', 'ARTICLE', 'Majelis Hakim wajib memberik an putusan penyelesaian perselisihan hubungan industrial dalam waktu selambat-lambatnya 50 (lima puluh) hari kerja terhitung sejak sidang pertama.', NULL, '{"law_id":"uu_2004_2","pasal":"103","heading":null,"bab":null,"bab_heading":null,"sort_order":304}', '/akn/id/act/uu/2004/2#pasal-103', 'berlaku', NULL, NULL, NULL, NULL);
