INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2004_2_pasal_105', 'Pasal 105', 'ARTICLE', 'Panitera Pengganti Pengadila n Hubungan Industrial dalam waktu selambat-lambatnya 7 (tuj uh) hari kerja setelah putusan Majelis Hakim dibacakan, harus sudah menyampaikan pemberitahuan putusan kepada pi hak yang tidak hadir dalam sidang sebagaimana dimaksud dalam Pasal 101 ayat (2).', NULL, '{"law_id":"uu_2004_2","pasal":"105","heading":null,"bab":null,"bab_heading":null,"sort_order":306}', '/akn/id/act/uu/2004/2#pasal-105', 'berlaku', NULL, NULL, NULL, NULL);
