INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2004_2_pasal_107', 'Pasal 107', 'ARTICLE', 'Panitera Pengadilan Negeri da lam waktu selambat-lambatnya 7 (tujuh) hari kerja setelah salin an putusan diterbitkan harus sudah mengirimkan salinan putusan kepada para pihak.', NULL, '{"law_id":"uu_2004_2","pasal":"107","heading":null,"bab":null,"bab_heading":null,"sort_order":308}', '/akn/id/act/uu/2004/2#pasal-107', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2004_2_pasal_108', 'Pasal 108', 'ARTICLE', 'Ketua Majelis Hakim Pengadila n Hubungan Industrial dapat mengeluarkan putusan yang dapa t dilaksanakan lebih dahulu, meskipun putusannya diajukan perlawanan atau kasasi.', NULL, '{"law_id":"uu_2004_2","pasal":"108","heading":null,"bab":null,"bab_heading":null,"sort_order":309}', '/akn/id/act/uu/2004/2#pasal-108', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2004_2_pasal_109', 'Pasal 109', 'ARTICLE', 'Putusan Pengadilan Hubungan Industrial pada Pengadilan Negeri mengenai perselisihan kepentingan dan perselisihan antar serikat pekerja/serikat buruh dalam satu perusahaan merupakan putusan akhir dan bersifat tetap.', NULL, '{"law_id":"uu_2004_2","pasal":"109","heading":null,"bab":null,"bab_heading":null,"sort_order":310}', '/akn/id/act/uu/2004/2#pasal-109', 'berlaku', NULL, NULL, NULL, NULL);
