INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_26', 'Pasal 26', 'ARTICLE', 'Selain harus memiliki persyaratan sebagaimana dimaksud dalam Pasal 25, calon anggota Dewan Pengawas harus memenuhi persyaratan khusus, yaitu memiliki kompetensi dan pengalaman di bidang manajemen, khususnya di bidang pengawasan paling sedikit 5 (lima) tahun.', NULL, '{"law_id":"uu_2011_24","pasal":"26","heading":null,"bab":null,"bab_heading":null,"sort_order":95}', '/akn/id/act/uu/2011/24#pasal-26', 'diubah', NULL, NULL, NULL, NULL);
