INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_35', 'Pasal 35', 'ARTICLE', 'Dalam hal anggota Dewan Pengawas atau anggota Direksi berhenti sebagaimana dimaksud dalam Pasal 32 huruf a atau diberhentikan sebagaimana dimaksud dalam Pasal 34, Presiden mengangkat anggota Dewan Pengawas atau anggota Direksi pengganti untuk meneruskan sisa masa jabatan yang digantikan.', NULL, '{"law_id":"uu_2011_24","pasal":"35","heading":null,"bab":null,"bab_heading":null,"sort_order":125}', '/akn/id/act/uu/2011/24#pasal-35', 'diubah', NULL, NULL, NULL, NULL);
