INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_42', 'Pasal 42', 'ARTICLE', 'Modal awal sebagaimana dimaksud dalam Pasal 41 ayat (1) huruf a untuk BPJS Kesehatan dan BPJS Ketenagakerjaan ditetapkan masing-masing paling banyak Rp2.000.000.000.000,00 (dua triliun rupiah) yang bersumber dari Anggaran Pendapatan dan Belanja Negara.', NULL, '{"law_id":"uu_2011_24","pasal":"42","heading":null,"bab":null,"bab_heading":null,"sort_order":161}', '/akn/id/act/uu/2011/24#pasal-42', 'diubah', NULL, NULL, NULL, NULL);
