INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_50', 'Pasal 50', 'ARTICLE', 'Dalam hal pengaduan tidak dapat diselesaikan oleh unit pengendali mutu pelayanan dan penanganan pengaduan Peserta melalui mekanisme mediasi tidak dapat terlaksana, penyelesaiannya dapat diajukan ke pengadilan negeri di wilayah tempat tinggal pemohon.', NULL, '{"law_id":"uu_2011_24","pasal":"50","heading":null,"bab":null,"bab_heading":null,"sort_order":197}', '/akn/id/act/uu/2011/24#pasal-50', 'diubah', NULL, NULL, NULL, NULL);
