INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_54', 'Pasal 54', 'ARTICLE', 'Anggota Dewan Pengawas atau anggota Direksi yang melanggar larangan ketentuan sebagaimana dimaksud dalam Pasal 52 huruf g, huruf h, huruf i, huruf j, huruf k, huruf l, atau huruf m dipidana dengan pidana penjara paling lama 8 (delapan) tahun dan pidana denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah).', NULL, '{"law_id":"uu_2011_24","pasal":"54","heading":null,"bab":"XV","bab_heading":"KETENTUAN PIDANA","sort_order":212}', '/akn/id/act/uu/2011/24#pasal-54', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_55', 'Pasal 55', 'ARTICLE', 'Pemberi Kerja yang melanggar ketentuan sebagaimana dimaksud dalam Pasal 19 ayat (1) atau ayat (2) dipidana dengan pidana penjara paling lama 8 (delapan) tahun atau pidana denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah).', NULL, '{"law_id":"uu_2011_24","pasal":"55","heading":null,"bab":"XV","bab_heading":"KETENTUAN PIDANA","sort_order":213}', '/akn/id/act/uu/2011/24#pasal-55', 'diubah', NULL, NULL, NULL, NULL);
