INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_63', 'Pasal 63', 'ARTICLE', 'Untuk pertama kali, Dewan Komisaris dan Direksi PT Jamsostek (Persero) diangkat menjadi anggota Dewan Pengawas dan anggota Direksi BPJS Ketenagakerjaan untuk jangka waktu paling lama 2 (dua) tahun sejak BPJS Ketenagakerjaan mulai beroperasi.', NULL, '{"law_id":"uu_2011_24","pasal":"63","heading":null,"bab":"XVIII","bab_heading":"KETENTUAN PENUTUP","sort_order":232}', '/akn/id/act/uu/2011/24#pasal-63', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_64', 'Pasal 64', 'ARTICLE', 'BPJS Ketenagakerjaan mulai beroperasi menyelenggarakan program jaminan kecelakaan kerja, program jaminan hari tua, program jaminan pensiun, dan program jaminan kematian bagi Peserta, selain peserta program yang dikelola PT TASPEN (Persero) dan PT ASABRI (Persero), sesuai dengan ketentuan Pasal 29 sampai dengan Pasal 46 Undang-Undang Nomor 40 Tahun 2004 tentang Sistem Jaminan Sosial Nasional (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 150, Tambahan Lembaran Negara Republik Indonesia Nomor 4456), paling lambat tanggal 1 Juli 2015.', NULL, '{"law_id":"uu_2011_24","pasal":"64","heading":null,"bab":"XVIII","bab_heading":"KETENTUAN PENUTUP","sort_order":233}', '/akn/id/act/uu/2011/24#pasal-64', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_65', 'Pasal 65', 'ARTICLE', '', NULL, '{"law_id":"uu_2011_24","pasal":"65","heading":null,"bab":"XVIII","bab_heading":"KETENTUAN PENUTUP","sort_order":234}', '/akn/id/act/uu/2011/24#pasal-65', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_66', 'Pasal 66', 'ARTICLE', 'Ketentuan mengenai tata cara pengalihan program Asuransi Sosial Angkatan Bersenjata Republik Indonesia dan program pembayaran pensiun dari PT ASABRI (Persero) dan pengalihan program tabungan hari tua dan program pembayaran pensiun dari PT TASPEN (Persero) ke BPJS Ketenagakerjaan diatur dengan Peraturan Pemerintah.', NULL, '{"law_id":"uu_2011_24","pasal":"66","heading":null,"bab":"XVIII","bab_heading":"KETENTUAN PENUTUP","sort_order":237}', '/akn/id/act/uu/2011/24#pasal-66', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_67', 'Pasal 67', 'ARTICLE', 'Ketentuan Pasal 142 ayat (2) huruf a Undang-Undang Nomor 40 Tahun 2007 tentang Perseroan Terbatas (Lembaran Negara Republik Indonesia Tahun 2007 Nomor 106, Tambahan Lembaran Negara Republik Indonesia Nomor 4756) dan Pasal 64 ayat (1) Undang-Undang Nomor 19 Tahun 2003 tentang Badan Usaha Milik Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 70, Tambahan Lembaran Negara Republik Indonesia Nomor 4297) tidak berlaku untuk pembubaran PT Askes (Persero) dan PT Jamsostek (Persero) sebagaimana dimaksud dalam Pasal 60 ayat (3) huruf a dan Pasal 62 ayat (2) huruf a.', NULL, '{"law_id":"uu_2011_24","pasal":"67","heading":null,"bab":"XVIII","bab_heading":"KETENTUAN PENUTUP","sort_order":238}', '/akn/id/act/uu/2011/24#pasal-67', 'diubah', NULL, NULL, NULL, NULL);
