INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_24_pasal_69', 'Pasal 69', 'ARTICLE', 'Pada saat mulai beroperasinya BPJS Ketenagakerjaan sebagaimana dimaksud dalam Pasal 64, Undang-Undang Nomor 3 Tahun 1992 tentang Jaminan Sosial Tenaga Kerja (Lembaran Negara Republik Indonesia Tahun 1992 Nomor 14, Tambahan Lembaran Negara Republik Indonesia Nomor 3468) dicabut dan dinyatakan tidak berlaku lagi.', NULL, '{"law_id":"uu_2011_24","pasal":"69","heading":null,"bab":"XVIII","bab_heading":"KETENTUAN PENUTUP","sort_order":240}', '/akn/id/act/uu/2011/24#pasal-69', 'diubah', NULL, NULL, NULL, NULL);
