INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_35_pasal_59', 'Pasal 59', 'ARTICLE', 'Pengusaha pada usaha mikro dan usaha kecil wajib membayar uang pesangon, uang penghargaan masa kerja, uang penggantian hak, dan/atau uang pisah bagi Pekerja/Buruh yang mengalami Pemutusan Hubungan Kerja dengan besaran ditentukan berdasarkan kesepakatan antara Pengusaha pada usaha mikro dan usaha kecil dengan Pekerja/Buruh.', NULL, '{"law_id":"pp_2021_35","pasal":"59","heading":null,"bab":null,"bab_heading":null,"sort_order":198}', '/akn/id/act/pp/2021/35#pasal-59', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_35_pasal_60', 'Pasal 60', 'ARTICLE', 'Pengawasan ketenagakerjaan terhadap penerapan ketentuan dalam Peraturan Pemerintah ini dilaksanakan oleh Pengawas Ketenagakerjaan pada kementerian yang menyelenggarakan urusan pemerintahan di bidang ketenagakerjaan dan/atau dinas yang menyelenggarakan urusan pemerintahan di bidang ketenagakerjaan provinsi.', NULL, '{"law_id":"pp_2021_35","pasal":"60","heading":null,"bab":"VI","bab_heading":"PENGAWASAN KETENAGAKERJAAN","sort_order":200}', '/akn/id/act/pp/2021/35#pasal-60', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_35_pasal_61', 'Pasal 61', 'ARTICLE', '', NULL, '{"law_id":"pp_2021_35","pasal":"61","heading":null,"bab":"VII","bab_heading":"SANKSI ADMINISTRATIF","sort_order":202}', '/akn/id/act/pp/2021/35#pasal-61', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_35_pasal_62', 'Pasal 62', 'ARTICLE', '', NULL, '{"law_id":"pp_2021_35","pasal":"62","heading":null,"bab":"VII","bab_heading":"SANKSI ADMINISTRATIF","sort_order":209}', '/akn/id/act/pp/2021/35#pasal-62', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_35_pasal_63', 'Pasal 63', 'ARTICLE', 'Pada saat Peraturan Pemerintah ini mulai berlaku, PKWT yang telah ada dan jangka waktunya belum berakhir masih tetap berlaku sampai dengan berakhirnya PKWT.', NULL, '{"law_id":"pp_2021_35","pasal":"63","heading":null,"bab":"VIII","bab_heading":"KETENTUAN PERALIHAN","sort_order":217}', '/akn/id/act/pp/2021/35#pasal-63', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_35_pasal_64', 'Pasal 64', 'ARTICLE', CAST(x'' AS TEXT), NULL, '{"law_id":"pp_2021_35","pasal":"64","heading":null,"bab":"X","bab_heading":"KETENTUAN PENUTUP","sort_order":220}', '/akn/id/act/pp/2021/35#pasal-64', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_35_pasal_65', 'Pasal 65', 'ARTICLE', 'Pada saat Peraturan Pemerintah ini mulai berlaku, semua peraturan perundang-undangan yang merupakan peraturan pelaksanaan dari Undang-Undang NOMOR 13 TAHUN 2003 tentang Ketenagakerjaan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 39, Tambahan Lembaran Negara Republik Indonesia Nomor 4279) yang mengatur mengenai waktu kerja pada sektor usaha atau pekerjaan tertentu, dinyatakan masih tetap berlaku sepanjang tidak bertentangan dengan ketentuan Peraturan Pemerintah ini.', NULL, '{"law_id":"pp_2021_35","pasal":"65","heading":null,"bab":"X","bab_heading":"KETENTUAN PENUTUP","sort_order":221}', '/akn/id/act/pp/2021/35#pasal-65', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_35_pasal_66', 'Pasal 66', 'ARTICLE', 'Peraturan Pemerintah ini mulai berlaku pada tanggal diundangkan.', NULL, '{"law_id":"pp_2021_35","pasal":"66","heading":null,"bab":"X","bab_heading":"KETENTUAN PENUTUP","sort_order":222}', '/akn/id/act/pp/2021/35#pasal-66', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_1', 'Pasal 1', 'ARTICLE', 'Dalam Peraturan Pemerintah ini yang dimaksud dengan:', NULL, '{"law_id":"pp_2021_36","pasal":"1","heading":null,"bab":"I","bab_heading":"KETENTUAN UMUM","sort_order":3}', '/akn/id/act/pp/2021/36#pasal-1', 'diubah', NULL, NULL, NULL, NULL);
