INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_3', 'Pasal 3', 'ARTICLE', 'Hak Pekerja/Buruh atas Upah timbul pada saat terjadi Hubungan Kerja antara Pekerja/Buruh dengan Pengusaha dan berakhir pada saat putusnya Hubungan Kerja.', NULL, '{"law_id":"pp_2021_36","pasal":"3","heading":null,"bab":"I","bab_heading":"KETENTUAN UMUM","sort_order":21}', '/akn/id/act/pp/2021/36#pasal-3', 'diubah', NULL, NULL, NULL, NULL);
