INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_19', 'Pasal 19', 'ARTICLE', 'Penetapan Upah sebulan berdasarkan satuan hasil sebagaimana dimaksud dalam Pasal 14 huruf b untuk pemenuhan pelaksanaan ketentuan peraturan perundang-undangan, ditetapkan berdasarkan Upah rata-rata 12 (dua belas) bulan terakhir yang diterima oleh Pekerja/Buruh.', NULL, '{"law_id":"pp_2021_36","pasal":"19","heading":null,"bab":"III","bab_heading":"UPAH BERDASARKAN SATUAN WAKTU DAN/ATAU SATUAN HASIL","sort_order":74}', '/akn/id/act/pp/2021/36#pasal-19', 'diubah', NULL, NULL, NULL, NULL);
