INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_37', 'Pasal 37', 'ARTICLE', 'Usaha mikro dan usaha kecil sebagaimana dimaksud dalam Pasal 36 ayat (1) harus memenuhi kriteria tertentu yang ditetapkan sesuai dengan ketentuan peraturan perundang-undangan.', NULL, '{"law_id":"pp_2021_36","pasal":"37","heading":null,"bab":"VI","bab_heading":"UPAH TERENDAH PADA USAHA MIKRO DAN USAHA KECIL","sort_order":160}', '/akn/id/act/pp/2021/36#pasal-37', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_38', 'Pasal 38', 'ARTICLE', CAST(x'' AS TEXT), NULL, '{"law_id":"pp_2021_36","pasal":"38","heading":null,"bab":"VI","bab_heading":"UPAH TERENDAH PADA USAHA MIKRO DAN USAHA KECIL","sort_order":161}', '/akn/id/act/pp/2021/36#pasal-38', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_39', 'Pasal 39', 'ARTICLE', 'Upah kerja lembur wajib dibayar oleh Pengusaha yang mempekerjakan Pekerja/Buruh melebihi waktu kerja, pada istirahat mingguan, atau pada hari libur resmi sebagai kompensasi kepada Pekerja/Buruh yang bersangkutan sesuai dengan ketentuan peraturan perundang-undangan.', NULL, '{"law_id":"pp_2021_36","pasal":"39","heading":null,"bab":null,"bab_heading":null,"sort_order":164}', '/akn/id/act/pp/2021/36#pasal-39', 'diubah', NULL, NULL, NULL, NULL);
