INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_42', 'Pasal 42', 'ARTICLE', '', NULL, '{"law_id":"pp_2021_36","pasal":"42","heading":null,"bab":null,"bab_heading":null,"sort_order":176}', '/akn/id/act/pp/2021/36#pasal-42', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_43', 'Pasal 43', 'ARTICLE', 'Pengusaha wajib membayar Upah kepada Pekerja/Buruh yang tidak masuk bekerja atau tidak melakukan pekerjaannya karena menjalankan kewajiban ibadah yang diperintahkan agamanya sebagaimana dimaksud dalam Pasal 40 ayat (4) huruf b, sebesar Upah yang diterima oleh Pekerja/Buruh dengan ketentuan hanya sekali selama Pekerja/Buruh bekerja di Perusahaan yang bersangkutan.', NULL, '{"law_id":"pp_2021_36","pasal":"43","heading":null,"bab":null,"bab_heading":null,"sort_order":180}', '/akn/id/act/pp/2021/36#pasal-43', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_44', 'Pasal 44', 'ARTICLE', 'Pengusaha wajib membayar Upah kepada Pekerja/Buruh yang tidak masuk bekerja dan/atau tidak melakukan pekerjaan karena melaksanakan tugas Serikat Pekerja/Serikat Buruh sebagaimana dimaksud dalam Pasal 40 ayat (4) huruf c, sebesar Upah yang biasa diterima oleh Pekerja/Buruh.', NULL, '{"law_id":"pp_2021_36","pasal":"44","heading":null,"bab":null,"bab_heading":null,"sort_order":181}', '/akn/id/act/pp/2021/36#pasal-44', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_45', 'Pasal 45', 'ARTICLE', 'Pengusaha wajib membayar Upah kepada Pekerja/Buruh yang tidak masuk bekerja dan/atau tidak melakukan pekerjaan karena melaksanakan tugas pendidikan dan/atau pelatihan dari Perusahaan sebagaimana dimaksud dalam Pasal 40 ayat (4) huruf d, sebesar Upah yang biasa diterima oleh Pekerja/Buruh.', NULL, '{"law_id":"pp_2021_36","pasal":"45","heading":null,"bab":null,"bab_heading":null,"sort_order":182}', '/akn/id/act/pp/2021/36#pasal-45', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_46', 'Pasal 46', 'ARTICLE', 'Pengusaha wajib membayar Upah kepada Pekerja/Buruh yang tidak masuk bekerja dan/atau tidak melakukan pekerjaan karena menjalankan hak waktu istirahat atau cutinya sebagaimana dimaksud dalam Pasal 40 ayat (5), sebesar Upah yang biasa diterima oleh Pekerja/Buruh.', NULL, '{"law_id":"pp_2021_36","pasal":"46","heading":null,"bab":null,"bab_heading":null,"sort_order":183}', '/akn/id/act/pp/2021/36#pasal-46', 'diubah', NULL, NULL, NULL, NULL);
