INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_50', 'Pasal 50', 'ARTICLE', 'Apabila Pekerja/Buruh jatuh pailit, Upah dan segala pembayaran yang timbul dari Hubungan Kerja tidak termasuk dalam kepailitan kecuali ditetapkan lain oleh hakim dengan ketentuan tidak melebihi 25% (dua puluh lima persen) dari Upah dan segala pembayaran yang timbul dari Hubungan Kerja yang harus dibayarkan.', NULL, '{"law_id":"pp_2021_36","pasal":"50","heading":null,"bab":null,"bab_heading":null,"sort_order":193}', '/akn/id/act/pp/2021/36#pasal-50', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_51', 'Pasal 51', 'ARTICLE', 'Apabila uang yang disediakan oleh Pengusaha untuk membayar Upah disita oleh juru sita berdasarkan perintah pengadilan maka penyitaan tersebut tidak boleh melebihi 20% (dua puluh persen) dari jumlah Upah yang harus dibayarkan.', NULL, '{"law_id":"pp_2021_36","pasal":"51","heading":null,"bab":null,"bab_heading":null,"sort_order":195}', '/akn/id/act/pp/2021/36#pasal-51', 'diubah', NULL, NULL, NULL, NULL);
