INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_78', 'Pasal 78', 'ARTICLE', 'Pengawasan ketenagakerjaan terhadap penerapan ketentuan dalam Peraturan Pemerintah ini dilaksanakan oleh Pengawas Ketenagakerjaan pada kementerian yang menyelenggarakan urusan pemerintahan di bidang ketenagakerjaan dan/atau dinas yang menyelenggarakan urusan pemerintahan di bidang ketenagakerjaan provinsi.', NULL, '{"law_id":"pp_2021_36","pasal":"78","heading":null,"bab":"XII","bab_heading":"PENGAWASAN","sort_order":312}', '/akn/id/act/pp/2021/36#pasal-78', 'diubah', NULL, NULL, NULL, NULL);
