INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_81', 'Pasal 81', 'ARTICLE', 'Pemerintah Daerah provinsi dan kabupaten/kota yang masih memberlakukan keputusan tentang Upah minimum yang bertentangan dengan Peraturan Pemerintah ini dikenai sanksi administratif sesuai dengan ketentuan peraturan perundang-undangan yang mengatur mengenai pemerintahan daerah.', NULL, '{"law_id":"pp_2021_36","pasal":"81","heading":null,"bab":"XIII","bab_heading":"SANKSI ADMINISTRATIF","sort_order":328}', '/akn/id/act/pp/2021/36#pasal-81', 'diubah', NULL, NULL, NULL, NULL);
