INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_84', 'Pasal 84', 'ARTICLE', 'Pada saat Peraturan Pemerintah ini mulai berlaku, semua peraturan perundang-undangan yang merupakan peraturan pelaksanaan dari Undang-Undang Nomor 13 Tahun 2003 tentang Ketenagakerjaan yang mengatur mengenai pengupahan dinyatakan masih tetap berlaku sepanjang tidak bertentangan dengan Peraturan Pemerintah ini.', NULL, '{"law_id":"pp_2021_36","pasal":"84","heading":null,"bab":"XIII","bab_heading":"SANKSI ADMINISTRATIF","sort_order":333}', '/akn/id/act/pp/2021/36#pasal-84', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_36_pasal_85', 'Pasal 85', 'ARTICLE', 'Pada saat Peraturan Pemerintah ini mulai berlaku, Peraturan Pemerintah Nomor 78 TAHUN 2015 tentang Pengupahan (Lembaran Negara Republik Indonesia Tahun 2015 Nomor 237, Tambahan Lembaran Negara Republik Indonesia Nomor 5747), dicabut dan dinyatakan tidak berlaku.', NULL, '{"law_id":"pp_2021_36","pasal":"85","heading":null,"bab":"XIII","bab_heading":"SANKSI ADMINISTRATIF","sort_order":334}', '/akn/id/act/pp/2021/36#pasal-85', 'diubah', NULL, NULL, NULL, NULL);
