INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_34_pasal_30', 'Pasal 30', 'ARTICLE', 'Pendidikan dan pelatihan bahasa Indonesia kepada TKA dapat dilaksanakan oleh Pemberi Kerja TKA atau bekerja sama dengan lembaga pendidikan atau lembaga pelatihan bahasa Indonesia.', NULL, '{"law_id":"pp_2021_34","pasal":"30","heading":null,"bab":"V","bab_heading":"PENDIDIKAN DAN PELATIHAN KERJA BAGI TENAGA KERJA PENDAMPING DAN TENAGA KERJA ASING","sort_order":132}', '/akn/id/act/pp/2021/34#pasal-30', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_34_pasal_31', 'Pasal 31', 'ARTICLE', 'Ketentuan lebih lanjut mengenai pelaksanaan pendidikan dan pelatihan kerja bagi Tenaga Kerja Pendamping TKA dan TKA sebagaimana dimaksud dalam Pasal 28 sampai dengan Pasal 30 diatur dengan Peraturan Menteri.', NULL, '{"law_id":"pp_2021_34","pasal":"31","heading":null,"bab":"V","bab_heading":"PENDIDIKAN DAN PELATIHAN KERJA BAGI TENAGA KERJA PENDAMPING DAN TENAGA KERJA ASING","sort_order":133}', '/akn/id/act/pp/2021/34#pasal-31', 'berlaku', NULL, NULL, NULL, NULL);
