INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_34_pasal_33', 'Pasal 33', 'ARTICLE', 'Menteri atau pejabat yang ditunjuk menyediakan data TKA yang dipekerjakan oleh Pemberi Kerja TKA secara daring dan dapat diakses oleh dinas yang menyelenggarakan urusan pemerintahan di bidang ketenagakerjaan provinsi dan kabupaten/kota sesuai dengan lokasi kerja TKA melalui sistem informasi ketenagakerjaan.', NULL, '{"law_id":"pp_2021_34","pasal":"33","heading":null,"bab":null,"bab_heading":null,"sort_order":140}', '/akn/id/act/pp/2021/34#pasal-33', 'berlaku', NULL, NULL, NULL, NULL);
