INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_34_pasal_41', 'Pasal 41', 'ARTICLE', 'Menteri atau pejabat yang ditunjuk menyampaikan pencabutan Pengesahan RPTKA kepada menteri yang menyelenggarakan urusan pemerintahan di bidang hukum dan hak asasi manusia atau pejabat yang ditunjuk untuk dilakukan tindakan keimigrasian sesuai dengan ketentuan peraturan perundangundangan di bidang keimigrasian.', NULL, '{"law_id":"pp_2021_34","pasal":"41","heading":null,"bab":"VII","bab_heading":"SANKSI ADMINISTRATIF","sort_order":170}', '/akn/id/act/pp/2021/34#pasal-41', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_34_pasal_42', 'Pasal 42', 'ARTICLE', 'Ketentuan lebih lanjut mengenai tata cara pengenaan sanksi administratif sebagaimana dimaksud dalam Pasal 36 sampai dengan Pasal 41 diatur dengan Peraturan Menteri.', NULL, '{"law_id":"pp_2021_34","pasal":"42","heading":null,"bab":"VII","bab_heading":"SANKSI ADMINISTRATIF","sort_order":171}', '/akn/id/act/pp/2021/34#pasal-42', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_34_pasal_43', 'Pasal 43', 'ARTICLE', 'Segala pendanaan yang diperlukan untuk pelaksanaan Peraturan Pemerintah ini dibebankan pada Anggaran Pendapatan dan Belanja Negara, Anggaran Pendapatan dan Belanja Daerah provinsi, serta sumber pendanaan lainnya yang sah sesuai dengan ketentuan peraturan perundang-undangan.', NULL, '{"law_id":"pp_2021_34","pasal":"43","heading":null,"bab":"VIII","bab_heading":"PENDANAAN","sort_order":173}', '/akn/id/act/pp/2021/34#pasal-43', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_34_pasal_44', 'Pasal 44', 'ARTICLE', 'Proses penggunaan TKA sebagaimana diatur dalam Peraturan Pemerintah ini dilakukan melalui penggunaan data secara bersama dan terintegrasi secara daring.', NULL, '{"law_id":"pp_2021_34","pasal":"44","heading":null,"bab":"IX","bab_heading":"KETENTUAN LAIN-LAIN","sort_order":175}', '/akn/id/act/pp/2021/34#pasal-44', 'berlaku', NULL, NULL, NULL, NULL);
