INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_34_pasal_46', 'Pasal 46', 'ARTICLE', 'Pada saat Peraturan Pemerintah ini mulai berlaku, Peraturan Presiden Nomor 20 TAHUN 2018 tentang Penggunaan Tenaga Kerja Asing (Lembaran Negara Republik Indonesia Tahun 2018 Nomor 39), dicabut dan dinyatakan tidak berlaku.', NULL, '{"law_id":"pp_2021_34","pasal":"46","heading":null,"bab":"XI","bab_heading":"KETENTUAN PENUTUP","sort_order":178}', '/akn/id/act/pp/2021/34#pasal-46', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_34_pasal_47', 'Pasal 47', 'ARTICLE', 'Pada saat Peraturan Pemerintah ini mulai berlaku, Peraturan Daerah dan Peraturan Kepala Daerah yang mengatur mengenai retribusi yang berasal dari perpanjangan izin mempekerjakan TKA wajib menyesuaikan dengan ketentuan dalam Peraturan Pemerintah ini paling lambat 3 (tiga) bulan terhitung sejak Peraturan Pemerintah ini berlaku.', NULL, '{"law_id":"pp_2021_34","pasal":"47","heading":null,"bab":"XI","bab_heading":"KETENTUAN PENUTUP","sort_order":179}', '/akn/id/act/pp/2021/34#pasal-47', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_34_pasal_48', 'Pasal 48', 'ARTICLE', 'Peraturan Pemerintah ini mulai berlaku pada tanggal 1 April 2021.', NULL, '{"law_id":"pp_2021_34","pasal":"48","heading":null,"bab":"XI","bab_heading":"KETENTUAN PENUTUP","sort_order":180}', '/akn/id/act/pp/2021/34#pasal-48', 'berlaku', NULL, NULL, NULL, NULL);
