INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2008_36_pasal_29', 'Pasal 29', 'ARTICLE', 'Apabila pajak yang terutang untuk suatu tahun pajak ternyata lebih besar daripada kredit pajak sebagaimana dimaksud dalam Pasal 28 ayat (1), kekurangan pembayaran pajak yang terutang harus dilunasi sebelum Surat Pemberitahuan Tahunan Pajak Penghasilan disampaikan.', NULL, '{"law_id":"uu_2008_36","pasal":"29","heading":null,"bab":null,"bab_heading":null,"sort_order":164}', '/akn/id/act/uu/2008/36#pasal-29', 'diubah', NULL, NULL, NULL, NULL);
