INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2008_36_pasal_31d', 'Pasal 31D', 'ARTICLE', 'Ketentuan mengenai perpajakan bagi bidang usaha pertambangan minyak dan gas bumi, bidang usaha panas bumi, bidang usaha pertambangan umum termasuk batubara, dan bidang usaha berbasis syariah diatur dengan atau berdasarkan Peraturan Pemerintah.', NULL, '{"law_id":"uu_2008_36","pasal":"31D","heading":null,"bab":null,"bab_heading":null,"sort_order":175}', '/akn/id/act/uu/2008/36#pasal-31D', 'diubah', NULL, NULL, NULL, NULL);
