INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2008_36_pasal_32', 'Pasal 32', 'ARTICLE', 'Tata cara pengenaan pajak dan sanksi-sanksi berkenaan dengan pelaksanaan Undang-Undang ini dilakukan sesuai dengan Undang-Undang Nomor 6 Tahun 1983 tentang Ketentuan Umum dan Tata Cara Perpajakan sebagaimana telah beberapa kali diubah terakhir dengan Undang-Undang Nomor 28 Tahun 2007 tentang Perubahan Ketiga atas Undang-Undang Nomor 6 Tahun 1983 tentang Ketentuan Umum dan Tata Cara Perpajakan.', NULL, '{"law_id":"uu_2008_36","pasal":"32","heading":null,"bab":null,"bab_heading":null,"sort_order":180}', '/akn/id/act/uu/2008/36#pasal-32', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2008_36_pasal_32b', 'Pasal 32B', 'ARTICLE', 'Ketentuan mengenai pengenaan pajak atas bunga atau diskonto Obligasi Negara yang diperdagangkan di negara lain berdasarkan perjanjian perlakuan timbal balik dengan negara lain tersebut diatur dengan Peraturan Pemerintah.', NULL, '{"law_id":"uu_2008_36","pasal":"32B","heading":null,"bab":null,"bab_heading":null,"sort_order":182}', '/akn/id/act/uu/2008/36#pasal-32B', 'diubah', NULL, NULL, NULL, NULL);
