INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2007_28_pasal_13a', 'Pasal 13A', 'ARTICLE', 'Wajib Pajak yang karena kealpaannya tidak menyampaikan Surat Pemberitahuan atau menyampaikan Surat Pemberitahuan, tetapi isinya tidak benar atau tidak lengkap, atau melampirkan keterangan yang isinya tidak benar sehingga dapat menimbulkan kerugian pada pendapatan negara, tidak dikenai sanksi pidana apabila kealpaan tersebut pertama kali dilakukan oleh Wajib Pajak dan Wajib Pajak tersebut wajib melunasi kekurangan pembayaran jumlah pajak yang terutang beserta sanksi administrasi berupa kenaikan sebesar 200% (dua ratus persen) dari jumlah pajak yang kurang dibayar yang ditetapkan melalui penerbitan Surat Ketetapan Pajak Kurang Bayar.', NULL, '{"law_id":"uu_2007_28","pasal":"13A","heading":null,"bab":null,"bab_heading":null,"sort_order":101}', '/akn/id/act/uu/2007/28#pasal-13A', 'diubah', NULL, NULL, NULL, NULL);
