INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2007_28_pasal_41a', 'Pasal 41A', 'ARTICLE', 'Setiap orang yang wajib memberikan keterangan atau bukti yang diminta sebagaimana dimaksud dalam Pasal 35 tetapi dengan sengaja tidak memberi keterangan atau bukti, atau memberi keterangan atau bukti yang tidak benar dipidana dengan pidana kurungan paling lama 1 (satu) tahun dan denda paling banyak Rp25.000.000,00 (dua puluh lima juta rupiah).', NULL, '{"law_id":"uu_2007_28","pasal":"41A","heading":null,"bab":null,"bab_heading":null,"sort_order":339}', '/akn/id/act/uu/2007/28#pasal-41A', 'diubah', NULL, NULL, NULL, NULL);
