INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_6_pasal_20', 'Pasal 20', 'ARTICLE', 'Pejabat Imigrasi yang bertugas berwenang naik ke alat angkut yang berlabuh di pelabuhan, mendarat di bandar udara, atau berada di pos lintas batas untuk kepentingan pemeriksaan K eimigrasian.', NULL, '{"law_id":"uu_2011_6","pasal":"20","heading":null,"bab":null,"bab_heading":null,"sort_order":63}', '/akn/id/act/uu/2011/6#pasal-20', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_6_pasal_21', 'Pasal 21', 'ARTICLE', 'Dalam hal terdapat dugaan adanya pelanggaran terhadap ketentuan sebagaimana dimaksud dalam Pasal 17 atau Pasal 18, Pejabat Imigrasi berwenang memerintahkan Penanggung Jawab Alat Angkut untuk menghentikan atau membawa alat angkutnya ke suatu tempat guna kepentingan pemeriksaan K eimigrasian.', NULL, '{"law_id":"uu_2011_6","pasal":"21","heading":null,"bab":null,"bab_heading":null,"sort_order":64}', '/akn/id/act/uu/2011/6#pasal-21', 'berlaku', NULL, NULL, NULL, NULL);
