INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_6_pasal_36', 'Pasal 36', 'ARTICLE', 'Visa dinas diberikan kepada Orang Asing pemegang Paspor dinas dan Paspor lain yang akan melakukan perjalanan ke W ilayah Indonesia dalam rangka melaksanakan tugas resmi yang tidak bersifat diplomatik dari pemerintah asing yang bersangkutan atau organisasi internasional.', NULL, '{"law_id":"uu_2011_6","pasal":"36","heading":null,"bab":null,"bab_heading":null,"sort_order":108}', '/akn/id/act/uu/2011/6#pasal-36', 'berlaku', NULL, NULL, NULL, NULL);
