INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_6_pasal_127', 'Pasal 127', 'ARTICLE', 'Setiap orang yang dengan sengaja dan melawan hukum menyimpan Dokumen Perjalanan Republik Indonesia palsu atau dipalsukan dengan maksud untuk digunakan bagi dirinya sendiri atau orang lain dipidana dengan pidana penjara paling lama 5 (lima) tahun dan pidana denda paling banyak Rp500.000.000,00 (lima ratus juta rupiah).', NULL, '{"law_id":"uu_2011_6","pasal":"127","heading":null,"bab":"XI","bab_heading":"KETENTUAN PIDANA","sort_order":344}', '/akn/id/act/uu/2011/6#pasal-127', 'berlaku', NULL, NULL, NULL, NULL);
