INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_6_pasal_129', 'Pasal 129', 'ARTICLE', 'Setiap orang yang dengan sengaja dan melawan hukum untuk kepentingan diri sendiri atau orang lain merusak, mengubah, menambah, mengurangi, atau menghilangkan , baik sebagian maupun seluruhnya , keterangan atau cap yang terdapat dalam Dokumen Perjalanan Republik Indonesia atau D okumen K eimigrasian lainnya dipidana dengan pidana penjara paling lama 5 (lima) tahun dan pidana denda paling banyak Rp500.000. 000,00 (lima ratus juta rupiah).', NULL, '{"law_id":"uu_2011_6","pasal":"129","heading":null,"bab":"XI","bab_heading":"KETENTUAN PIDANA","sort_order":346}', '/akn/id/act/uu/2011/6#pasal-129', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_6_pasal_130', 'Pasal 130', 'ARTICLE', 'Setiap orang yang dengan sengaja dan melawan hukum menguasai Dokumen Perjalanan atau Dokumen Keimigrasian lainnya milik orang lain dipidana dengan pidana penjara paling lama 2 (dua) tahun dan /atau pidana denda p aling banyak Rp 200.000.000,00 (dua ratus juta rupiah).', NULL, '{"law_id":"uu_2011_6","pasal":"130","heading":null,"bab":"XI","bab_heading":"KETENTUAN PIDANA","sort_order":347}', '/akn/id/act/uu/2011/6#pasal-130', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_6_pasal_131', 'Pasal 131', 'ARTICLE', 'Setiap orang yang dengan sengaja tanpa hak dan melawan hukum memiliki, menyimpan, merusak, menghilangkan, mengubah, menggandakan, menggunakan dan atau mengakses data K eimigrasian , baik secar a manual maupun elektronik , untuk kepentingan diri sendiri atau orang lain dipidana dengan pidana penjara paling lama 5 (lima) tahun dan pidana denda palin g banyak Rp 500.000.000,00 (lima ratus juta rupiah).', NULL, '{"law_id":"uu_2011_6","pasal":"131","heading":null,"bab":"XI","bab_heading":"KETENTUAN PIDANA","sort_order":348}', '/akn/id/act/uu/2011/6#pasal-131', 'berlaku', NULL, NULL, NULL, NULL);
