INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_2', 'Pasal 2', 'ARTICLE', '', NULL, '{"law_id":"uu_1960_5","pasal":"2","heading":null,"bab":"I","bab_heading":"DASAR-DASAR DAN KETENTUAN-KETENTUAN POKOK.","sort_order":10}', '/akn/id/act/uu/1960/5#pasal-2', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_3', 'Pasal 3', 'ARTICLE', 'Dengan mengingat ketentuan-ketentuan dalam pasal 1 dan 2 pelaksanaan hak ulayat dan hak-hak yang serupa itu dari masyarakat-masyarakat hukum adat, sepanjang menurut kenyataannya. masih ada, harus sedemikian rupa sehingga sesuai dengan kepentingan nasional dan Negara, yang berdasarkan atas persatuan bangsa serta tidak boleh bertentangan dengan Undang-undang dan peraturan-peraturan lain yang lebih tinggi.', NULL, '{"law_id":"uu_1960_5","pasal":"3","heading":null,"bab":"I","bab_heading":"DASAR-DASAR DAN KETENTUAN-KETENTUAN POKOK.","sort_order":15}', '/akn/id/act/uu/1960/5#pasal-3', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_4', 'Pasal 4', 'ARTICLE', '', NULL, '{"law_id":"uu_1960_5","pasal":"4","heading":null,"bab":"I","bab_heading":"DASAR-DASAR DAN KETENTUAN-KETENTUAN POKOK.","sort_order":16}', '/akn/id/act/uu/1960/5#pasal-4', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_5', 'Pasal 5', 'ARTICLE', 'Hukum agraria yang berlaku atas bumi, air dan ruang angkasa ialah hukum adat, sepanjang tidak bertentangan dengan kepentingan nasional dan Negara, yang berdasarkan atas persatuan bangsa, dengan sosialisme Indonesia serta dengan peraturan-peraturan yang tercantum dalam Undang-undang ini dan dengan peraturan perundangan lainnya, segala sesuatu dengan mengindahkan unsur-unsur yang bersandar pada hukum agama.', NULL, '{"law_id":"uu_1960_5","pasal":"5","heading":null,"bab":"I","bab_heading":"DASAR-DASAR DAN KETENTUAN-KETENTUAN POKOK.","sort_order":20}', '/akn/id/act/uu/1960/5#pasal-5', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_6', 'Pasal 6', 'ARTICLE', 'Semua hak atas tanah mempunyai fungsi sosial.', NULL, '{"law_id":"uu_1960_5","pasal":"6","heading":null,"bab":"I","bab_heading":"DASAR-DASAR DAN KETENTUAN-KETENTUAN POKOK.","sort_order":21}', '/akn/id/act/uu/1960/5#pasal-6', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_7', 'Pasal 7', 'ARTICLE', 'Untuk tidak merugikan kepentingan umum maka pemilikan dan penguasaan tanah yang melampaui batas tidak diperkenankan.', NULL, '{"law_id":"uu_1960_5","pasal":"7","heading":null,"bab":"I","bab_heading":"DASAR-DASAR DAN KETENTUAN-KETENTUAN POKOK.","sort_order":22}', '/akn/id/act/uu/1960/5#pasal-7', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_8', 'Pasal 8', 'ARTICLE', 'Atas dasar hak menguasai dari Negara sebagai yang dimaksud dalam pasal 2 diatur pengambilan kekayaan alam yang terkandung dalam bumi, air dan ruang angkasa.', NULL, '{"law_id":"uu_1960_5","pasal":"8","heading":null,"bab":"I","bab_heading":"DASAR-DASAR DAN KETENTUAN-KETENTUAN POKOK.","sort_order":23}', '/akn/id/act/uu/1960/5#pasal-8', 'berlaku', NULL, NULL, NULL, NULL);
