INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_15', 'Pasal 15', 'ARTICLE', 'Memelihara tanah, termasuk menambah kesuburannya serta mencegah kerusakannya adalah kewajiban tiap-tiap orang, badan hukum atau instansi yang mempunyai hubungan hukum dengan tanah itu, dengan memperhatikan pihak yang ekonomis lemah.', NULL, '{"law_id":"uu_1960_5","pasal":"15","heading":null,"bab":"I","bab_heading":"DASAR-DASAR DAN KETENTUAN-KETENTUAN POKOK.","sort_order":46}', '/akn/id/act/uu/1960/5#pasal-15', 'berlaku', NULL, NULL, NULL, NULL);
