INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_18', 'Pasal 18', 'ARTICLE', 'Untuk kepentingan umum, termasuk kepentingan bangsa dan Negara serta kepentingan bersama dari rakyat, hak-hak atas tanah dapat dicabut, dengan memberi ganti kerugian yang layak dan menurut cara yang diatur dengan Undang-undang.', NULL, '{"law_id":"uu_1960_5","pasal":"18","heading":null,"bab":null,"bab_heading":null,"sort_order":57}', '/akn/id/act/uu/1960/5#pasal-18', 'berlaku', NULL, NULL, NULL, NULL);
