INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_51', 'Pasal 51', 'ARTICLE', 'Hak tanggungan yang dapat dibebankan pada hak milik, hak guna-usaha dan hak guna-bangunan tersebut dalam pasal 25, 33 dan 39 diatur dengan Undang-undang.', NULL, '{"law_id":"uu_1960_5","pasal":"51","heading":null,"bab":null,"bab_heading":null,"sort_order":153}', '/akn/id/act/uu/1960/5#pasal-51', 'berlaku', NULL, NULL, NULL, NULL);
