INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_53', 'Pasal 53', 'ARTICLE', '', NULL, '{"law_id":"uu_1960_5","pasal":"53","heading":null,"bab":"IV","bab_heading":"KETENTUAN-KETENTUAN PERALIHAN.","sort_order":160}', '/akn/id/act/uu/1960/5#pasal-53', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_54', 'Pasal 54', 'ARTICLE', 'Berhubung dengan ketentuan-ketentuan dalam pasal 21 dan 26, maka jika seseorang yang disamping kewarganegaraan Indonesianya mempunyai kewarga-negaraan Republik Rakyat Tiongkok, telah menyatakan menolak kewarga-negaraan Republik Rakyat Tiongkok itu yang disahkan menurut peraturan perundangan yang bersangkutan, ia dianggap hanya berkewarga-negaraan Indonesia saja menurut pasal 21 ayat (1).', NULL, '{"law_id":"uu_1960_5","pasal":"54","heading":null,"bab":"IV","bab_heading":"KETENTUAN-KETENTUAN PERALIHAN.","sort_order":163}', '/akn/id/act/uu/1960/5#pasal-54', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_55', 'Pasal 55', 'ARTICLE', '', NULL, '{"law_id":"uu_1960_5","pasal":"55","heading":null,"bab":"IV","bab_heading":"KETENTUAN-KETENTUAN PERALIHAN.","sort_order":164}', '/akn/id/act/uu/1960/5#pasal-55', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_56', 'Pasal 56', 'ARTICLE', 'Selama Undang-undang mengenai hak milik sebagai tersebut dalam pasal 50 ayat (1) belum terbentuk, maka yang berlaku adalah ketentuan-ketentuan hukum adat setempat dan peraturan-peraturan lainnya mengenai hak-hak atas tanah yang memberi wewenang sebagaimana atau mirip dengan yang dimaksud dalam pasal 20, sepanjang tidak bertentangan dengan jiwa dan ketentuan-ketentuan Undang-undang ini.', NULL, '{"law_id":"uu_1960_5","pasal":"56","heading":null,"bab":"IV","bab_heading":"KETENTUAN-KETENTUAN PERALIHAN.","sort_order":167}', '/akn/id/act/uu/1960/5#pasal-56', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_57', 'Pasal 57', 'ARTICLE', 'Selama Undang-undang mengenai hak tanggungan tersebut dalam pasal 51 belum terbentuk, maka yang berlaku ialah ketentuan-ketentuan mengenai hypotheek tersebut dalam Kitab Undang-undang Hukum Perdata Indonesia dan Credietverband tersebut dalam Staatsblad .1908 No. 542 sebagai yang telah diubah dengan Staatsblad 1937 No. 190.', NULL, '{"law_id":"uu_1960_5","pasal":"57","heading":null,"bab":"IV","bab_heading":"KETENTUAN-KETENTUAN PERALIHAN.","sort_order":168}', '/akn/id/act/uu/1960/5#pasal-57', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_58', 'Pasal 58', 'ARTICLE', 'Selama peraturan-peraturan pelaksanaan Undang-undang ini belum terbentuk, maka peraturan-peraturan baik yang tertulis maupun yang tidak tertulis mengenai bumi dan air serta kekayaan alam yang terkandung didalamnya dan hak-hak atas tanah, yang ada pada mulai berlakunya Undang-undang ini, tetap berlaku, sepanjang tidak bertentangan dengan jiwa dari ketentuan-ketentuan dalam Undang-undang ini serta diberi tafsiran yang sesuai dengan itu.', NULL, '{"law_id":"uu_1960_5","pasal":"58","heading":null,"bab":"IV","bab_heading":"KETENTUAN-KETENTUAN PERALIHAN.","sort_order":169}', '/akn/id/act/uu/1960/5#pasal-58', 'berlaku', NULL, NULL, NULL, NULL);
