INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_v', 'Pasal V', 'ARTICLE', 'Hak opstal dan hak erfpacht untuk perumahan, yang ada pada mulai berlakunya Undang-undang ini, sejak saat tersebut menjadi hak guna bangunan tersebut dalam pasal 35 ayat (1) yang berlangsung selama sisa waktu hak opstal dan hak erfpacht tersebut, tetapi selama-lamanya 20 tahun.', NULL, '{"law_id":"uu_1960_5","pasal":"V","heading":null,"bab":null,"bab_heading":null,"sort_order":188}', '/akn/id/act/uu/1960/5#pasal-V', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_vi', 'Pasal VI', 'ARTICLE', 'Hak-hak atas tanah yang memberi wewenang sebagaimana atau mirip dengan hak yang dimaksud dalam pasal 41 ayat (1) seperti yang disebut dengan nama sebagai dibawah, yang ada pada mulai berlakunya Undang-undang ini, yaitu : hak vruchtgebruik, gebruik, grant controleur, bruikleen, ganggam bauntuik, anggaduh, bengkok, lungguh, pituwas, dan hak-hak lain dengan nama apapun juga, yang akan ditegaskan lebih lanjut oleh Menteri Agraria, sejak mulai berlakunya Undang-undang ini menjadi hak pakai tersebut dalam pasal 41 ayat (1) yang memberi wewenang dan kewajiban sebagaimana yang dipunyai oleh pemegang haknya pada mulai berlakunya Undang-undang ini, sepanjang tidak bertentangan dengan jiwa dan ketentuan-ketentuan Undang-undang ini.', NULL, '{"law_id":"uu_1960_5","pasal":"VI","heading":null,"bab":null,"bab_heading":null,"sort_order":189}', '/akn/id/act/uu/1960/5#pasal-VI', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_vii', 'Pasal VII', 'ARTICLE', '', NULL, '{"law_id":"uu_1960_5","pasal":"VII","heading":null,"bab":null,"bab_heading":null,"sort_order":190}', '/akn/id/act/uu/1960/5#pasal-VII', 'berlaku', NULL, NULL, NULL, NULL);
