INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1960_5_pasal_ix', 'Pasal IX', 'ARTICLE', 'Hal-hal yang perlu untuk menyelenggarakan ketentuan-ketentuan dalam pasal-pasal diatas diatur lebih lanjut oleh Menteri Agraria.', NULL, '{"law_id":"uu_1960_5","pasal":"IX","heading":null,"bab":null,"bab_heading":null,"sort_order":197}', '/akn/id/act/uu/1960/5#pasal-IX', 'berlaku', NULL, NULL, NULL, NULL);
