INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2012_2_pasal_24', 'Pasal 24', 'ARTICLE', 'Penetapan lokasi pembangunan untuk Kepentingan Umum sebagaimana dimaksud dalam Pasal 19 ayat (6) atau Pasal 22 ayat (1) diberikan dalam waktu 2 (dua) tahun dan dapat diperpanjang paling lama 1 (satu) tahun.', NULL, '{"law_id":"uu_2012_2","pasal":"24","heading":null,"bab":null,"bab_heading":null,"sort_order":72}', '/akn/id/act/uu/2012/2#pasal-24', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2012_2_pasal_25', 'Pasal 25', 'ARTICLE', 'Dalam hal jangka waktu penetapan lokasi pembangunan untuk Kepentingan Umum sebagaimana dimaksud dalam Pasal 24 tidak terpenuhi, penetapan lokasi pembangunan untuk Kepentingan Umum dilaksanakan proses ulang terhadap sisa tanah yang belum selesai pengadaannya.', NULL, '{"law_id":"uu_2012_2","pasal":"25","heading":null,"bab":null,"bab_heading":null,"sort_order":73}', '/akn/id/act/uu/2012/2#pasal-25', 'diubah', NULL, NULL, NULL, NULL);
