INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2012_2_pasal_39', 'Pasal 39', 'ARTICLE', 'Dalam hal Pihak yang Berhak menolak bentuk dan/atau besarnya Ganti Kerugian, tetapi tidak mengajukan keberatan dalam waktu sebagaimana dimaksud dalam Pasal 38 ayat (1), karena hukum Pihak yang Berhak dianggap menerima bentuk dan besarnya Ganti Kerugian sebagaimana dimaksud dalam Pasal 37 ayat (1).', NULL, '{"law_id":"uu_2012_2","pasal":"39","heading":null,"bab":null,"bab_heading":null,"sort_order":119}', '/akn/id/act/uu/2012/2#pasal-39', 'diubah', NULL, NULL, NULL, NULL);
