INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_18_pasal_81', 'Pasal 81', 'ARTICLE', 'Ketentuan mengenai subjek, jangka waktu, pembebanan, peralihan dan pelepasan, dan pembatalan Hak Pengelolaan, hak guna bangunan, dan hak pakai atas Tanah berlaku secara mutatis mutandis terhadap ketentuan mengenai subjek, jangka waktu, pembebanan, peralihan dan pelepasan, dan pembatalan Hak Pengelolaan, hak guna bangunan, dan hak pakai pada Ruang Atas Tanah atau Ruang Bawah Tanah.', NULL, '{"law_id":"pp_2021_18","pasal":"81","heading":null,"bab":null,"bab_heading":null,"sort_order":302}', '/akn/id/act/pp/2021/18#pasal-81', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_18_pasal_82', 'Pasal 82', 'ARTICLE', '', NULL, '{"law_id":"pp_2021_18","pasal":"82","heading":null,"bab":null,"bab_heading":null,"sort_order":304}', '/akn/id/act/pp/2021/18#pasal-82', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_18_pasal_83', 'Pasal 83', 'ARTICLE', 'Ketentuan lebih lanjut mengenai subjek, objek, jangka waktu, terjadinya hak, tata cara dan syarat permohonan pemberian, perpanjangan, pembaruan, dan pendaftaran, kewajiban, larangan dan hak, pembebanan, peralihan" pelepasan dan perubahan, serta hapusnya Hak Pengelolaan, hak guna bangunan, dan hak pakai pada Ruang Atas Tanah atau Ruang Bawah Tanah sebagaimana dimaksud dalam Pasal 74 sampai dengan Pasal 82 Ciatur dalam Peraturan Menteri.', NULL, '{"law_id":"pp_2021_18","pasal":"83","heading":null,"bab":null,"bab_heading":null,"sort_order":307}', '/akn/id/act/pp/2021/18#pasal-83', 'berlaku', NULL, NULL, NULL, NULL);
