INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_18_pasal_94', 'Pasal 94', 'ARTICLE', 'Hak guna bangunan dan hak pakai yang dimiliki oleh Warga Negara Indonesia, yang digunakan Can dimanl''aatkan untuk rumah tinggal termasuk rumah toko dan rumah kantor, dapat diberikan hak milik atas permohonan pemegang hak.', NULL, '{"law_id":"pp_2021_18","pasal":"94","heading":null,"bab":null,"bab_heading":null,"sort_order":346}', '/akn/id/act/pp/2021/18#pasal-94', 'berlaku', NULL, NULL, NULL, NULL);
