INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_18_pasal_97', 'Pasal 97', 'ARTICLE', 'Surat keterangan tanah, surat keterangan ganti rugi, surat keterangan desa, dan lainnya yang sejenis yang dimaksudkan sebagai keterangan atas penguasaan dan pemilikan Tanah yang dikeluarkan oleh kepala desa/lurahf camat hanya dapat digunakan sebagai petunjuk dalam rangka Pendaftaran Tanah.', NULL, '{"law_id":"pp_2021_18","pasal":"97","heading":null,"bab":null,"bab_heading":null,"sort_order":355}', '/akn/id/act/pp/2021/18#pasal-97', 'berlaku', NULL, NULL, NULL, NULL);
