INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_18_pasal_99', 'Pasal 99', 'ARTICLE', 'Ketentuan lebih lanjut mengenai penyelenggaraan Pendaltaran Tanah secara elektronik, penyimpanan dan penyajian data dan/atau dokumen elektronik, bentuk, isi dan tata cara pembuatan akta Pejabat Pembuat Akta Tanah secara elektronik, percepatan Pendaftaran Tanah, pendaftaran hak tanggungan secara elektronik, pencatatan perjanjian pengikatan jual beli dan perjanjian sewa, pencatatan objek perkara dan perintah stafus euo, perubahan hak guna bangunan dan hak pakai menjadi hak milik, dan Pendaftaran Tanah bekas hak barat atau Tanah bekas milik adat serta Tanah swapraja atau bekas swapraja sebagaimana dimaksud dalam Pasal 84 sampai dengan Pasal 98 diatur dalam Peraturan Menteri.', NULL, '{"law_id":"pp_2021_18","pasal":"99","heading":null,"bab":null,"bab_heading":null,"sort_order":362}', '/akn/id/act/pp/2021/18#pasal-99', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('pp_2021_18_pasal_100', 'Pasal 100', 'ARTICLE', 'Dalam hal Peraturan Pemerintah ini memberikan oilihan tidak mengatur, tidak lengkap, atau tidak jelas, danlatatr adanya stagnasi pemerintahan, Menteri dapat melakukan diskresi rrntuk mengatasi persoalan konkret dalam penyelenggaraan urusan pemerintahan di bidang Hak Pengelolaan, Hak Atas Tanah, Satuan Rumah Susun, dan Pendaftaran Tanah.', NULL, '{"law_id":"pp_2021_18","pasal":"100","heading":null,"bab":"VIII","bab_heading":"KETENTUAN LAIN-LAIN","sort_order":364}', '/akn/id/act/pp/2021/18#pasal-100', 'berlaku', NULL, NULL, NULL, NULL);
