INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2020_3_pasal_161', 'Pasal 161', 'ARTICLE', 'Setiap orang yang menampung, memanfaatkan, melakukan Pengolahan danf atau Pemurnian, Pengembangan dan/atau Pemanfaatan, Pengangkutan, Penjualan Mineral dan/atau Batubara yang tidak berasal dari pemegang IUP, IUPK, IPR, SIPB atau izin sebagaimana dimaksud dalam Pasal 35 ayat (3) huruf c dan huruf g, Pasal 104, atau Pasal 105 dipidana dengan pidana penjara paling lama 5 (lima) tahun dan denda paling banyak Rp 100.000.00O.00O,00 (seratus miliar rupiah).', NULL, '{"law_id":"uu_2020_3","pasal":"161","heading":null,"bab":null,"bab_heading":null,"sort_order":435}', '/akn/id/act/uu/2020/3#pasal-161', 'diubah', NULL, NULL, NULL, NULL);
