INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2020_3_pasal_172a', 'Pasal 172A', 'ARTICLE', 'Ketentuan terkait hak, kewajiban, dan larangan bagi pemegang IUPK pada tahap kegiatan Operasi Produksi sebagaimana diatur dalam Undang-Undang ini berlaku secara mutatis mutandis terhadap IUPK sebagai Kelanjutan Operasi Kontrak/Perjanjian kecuali yang ditentukan lain dalam Undang-Undang ini.', NULL, '{"law_id":"uu_2020_3","pasal":"172A","heading":null,"bab":null,"bab_heading":null,"sort_order":468}', '/akn/id/act/uu/2020/3#pasal-172A', 'diubah', NULL, NULL, NULL, NULL);
