INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2020_3_pasal_172e', 'Pasal 172E', 'ARTICLE', 'Rencana pengelolaan Mineral dan Batubara nasional sebagaimana dimaksud dalam Pasal 8A wajib ditetapkan oleh Menteri dalam jangka waktu paling lambat 2 (dua) tahun sejak Undang-Undang ini mulai berlaku.', NULL, '{"law_id":"uu_2020_3","pasal":"172E","heading":null,"bab":null,"bab_heading":null,"sort_order":474}', '/akn/id/act/uu/2020/3#pasal-172E', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2020_3_pasal_173a', 'Pasal 173A', 'ARTICLE', 'Ketentuan dalam Undang-Undang ini berlaku juga bagi Provinsi Daerah Istimewa Yograkarta, Provinsi Daerah Khusus Ibukota Jakarta, Provinsi Aceh, Provinsi Papua Barat, dan Provinsi Papua sepanjang tidak diatur secara khusus dalam Undang-Undang yang mengatur keistimewaan dan kekhususan Daerah tersebut.', NULL, '{"law_id":"uu_2020_3","pasal":"173A","heading":null,"bab":null,"bab_heading":null,"sort_order":476}', '/akn/id/act/uu/2020/3#pasal-173A', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2020_3_pasal_173b', 'Pasal 173B', 'ARTICLE', 'Pada saat Undang-Undang ini mulai berlaku, ketentuan mengenai pembagian urusan pemerintahan konkuren antara Pemerintah Pusat dan Pemerintah Daerah provinsi dan Pemerintah Daerah kabupaten/kota pada Angka I Matriks Pembagian Urusan Pemerintahan Konkuren Antara Pemerintah Pusat dan Daerah provinsi dan Daerah Kabupaten lKota huruf CC Pembagian Urusan Pemerintahan Bidang Energi dan Sumber Daya Mineral Nomor 2 Sub Urusan Mineral dan Batubara yang tertuang dalam Lampiran yang merupakan bagian tidak terpisahkan dari Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2014 Nomor 244, Tambahan Lembaran Negara Republik Indonesia Nomor 5587) sebagaimana telah beberapa kali diubah terakhir dengan Undang-Undang Nomor 9 Tahun 2015 tentang Perubahan Kedua atas Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 20LS Nomor 58, Tambahan Lembaran Negara Republik Indonesia Nomor 56791, dicabut dan dinyatakan tidak berlaku.', NULL, '{"law_id":"uu_2020_3","pasal":"173B","heading":null,"bab":null,"bab_heading":null,"sort_order":477}', '/akn/id/act/uu/2020/3#pasal-173B', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2020_3_pasal_173c', 'Pasal 173C', 'ARTICLE', '', NULL, '{"law_id":"uu_2020_3","pasal":"173C","heading":null,"bab":null,"bab_heading":null,"sort_order":478}', '/akn/id/act/uu/2020/3#pasal-173C', 'diubah', NULL, NULL, NULL, NULL);
