INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2011_21_pasal_58', 'Pasal 58', 'ARTICLE', 'Paling lama 7 (tujuh) bulan sejak Undang-undang ini diundangkan, Gubernur Bank Indonesia dan Menteri Keuangan masing-masing mengusulkan calon anggota Dewan Komisioner Ex-officio Bank Indonesia sebagaimana dimaksud Pasal 10 ayat (4) huruf h dan Ex-officio Kementerian Keuangan sebagaimana dimaksud Pasal 10 ayat (4) huruf i kepada Presiden untuk diangkat dan ditetapkan sebagai anggota Dewan Komisioner.', NULL, '{"law_id":"uu_2011_21","pasal":"58","heading":null,"bab":"XIII","bab_heading":"KETENTUAN PERALIHAN","sort_order":248}', '/akn/id/act/uu/2011/21#pasal-58', 'diubah', NULL, NULL, NULL, NULL);
