INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2014_33_pasal_35', 'Pasal 35', 'ARTICLE', 'Sertifikat Halal sebagaimana dimaksud dalam Pasal 34 ayat (1) diterbitkan oleh BPJPH paling lama 7 (tujuh) hari kerja terhitung sejak keputusan kehalalan Produk diterima dari MUI.', NULL, '{"law_id":"uu_2014_33","pasal":"35","heading":null,"bab":null,"bab_heading":null,"sort_order":108}', '/akn/id/act/uu/2014/33#pasal-35', 'diubah', NULL, NULL, NULL, NULL);
