INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2014_33_pasal_54', 'Pasal 54', 'ARTICLE', 'BPJPH dapat memberikan penghargaan kepada masyarakat yang berperan serta dalam penyelenggaraan JPH.', NULL, '{"law_id":"uu_2014_33","pasal":"54","heading":null,"bab":"VIII","bab_heading":"PERAN SERTA MASYARAKAT","sort_order":157}', '/akn/id/act/uu/2014/33#pasal-54', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2014_33_pasal_55', 'Pasal 55', 'ARTICLE', 'Ketentuan lebih lanjut mengenai tata cara peran serta masyarakat dan pemberian penghargaan diatur dalam Peraturan Menteri.', NULL, '{"law_id":"uu_2014_33","pasal":"55","heading":null,"bab":"VIII","bab_heading":"PERAN SERTA MASYARAKAT","sort_order":158}', '/akn/id/act/uu/2014/33#pasal-55', 'diubah', NULL, NULL, NULL, NULL);
