INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2014_33_pasal_57', 'Pasal 57', 'ARTICLE', 'Setiap orang yang terlibat dalam penyelenggaraan proses JPH yang tidak menjaga kerahasiaan formula yang tercantum dalam informasi yang diserahkan Pelaku Usaha sebagaimana dimaksud dalam Pasal 43 dipidana dengan pidana penjara paling lama 2 (dua) tahun atau pidana denda paling banyak Rp2.000.000.000,00 (dua miliar rupiah).', NULL, '{"law_id":"uu_2014_33","pasal":"57","heading":null,"bab":"IX","bab_heading":"KETENTUAN PIDANA","sort_order":161}', '/akn/id/act/uu/2014/33#pasal-57', 'diubah', NULL, NULL, NULL, NULL);
