INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_66', 'Pasal 66', 'ARTICLE', 'Setiap Orang dilarang membuat Data Pribadi palsu atau memalsukan Data Pribadi dengan maksud untuk menguntungkan diri sendiri atau orang lain yang dapat mengakibatkan kerugian bagi orang lain.', NULL, '{"law_id":"uu_2022_27","pasal":"66","heading":null,"bab":"XIII","bab_heading":"LARANGAN DALAM PENGGUNAAN DATA PRIBADI","sort_order":194}', '/akn/id/act/uu/2022/27#pasal-66', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_67', 'Pasal 67', 'ARTICLE', '', NULL, '{"law_id":"uu_2022_27","pasal":"67","heading":null,"bab":"XIV","bab_heading":"KETENTUAN PIDANA","sort_order":196}', '/akn/id/act/uu/2022/27#pasal-67', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_68', 'Pasal 68', 'ARTICLE', 'Setiap Orang yang dengan sengaja membuat Data Pribadi palsu atau memalsukan Data Pribadi dengan maksud untuk menguntungkan diri sendiri atau orang lain yang dapat mengakibatkan kerugian bagi orang lain sebagaimana dimaksud dalam Pasal 66 dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau pidana denda paling banyak Rp6.000.000.000,00 (enam miliar rupiah).', NULL, '{"law_id":"uu_2022_27","pasal":"68","heading":null,"bab":"XIV","bab_heading":"KETENTUAN PIDANA","sort_order":200}', '/akn/id/act/uu/2022/27#pasal-68', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_69', 'Pasal 69', 'ARTICLE', 'Selain dijatuhi pidana sebagaimana dimaksud dalam Pasal 67 dan Pasal 68 juga dapat dijatuhi pidana tambahan berupa perampasan keuntungan dan/atau harta kekayaan yang diperoleh atau hasil dari tindak pidana dan pembayaran ganti kerugian.', NULL, '{"law_id":"uu_2022_27","pasal":"69","heading":null,"bab":"XIV","bab_heading":"KETENTUAN PIDANA","sort_order":201}', '/akn/id/act/uu/2022/27#pasal-69', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_70', 'Pasal 70', 'ARTICLE', '', NULL, '{"law_id":"uu_2022_27","pasal":"70","heading":null,"bab":"XIV","bab_heading":"KETENTUAN PIDANA","sort_order":202}', '/akn/id/act/uu/2022/27#pasal-70', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_71', 'Pasal 71', 'ARTICLE', '', NULL, '{"law_id":"uu_2022_27","pasal":"71","heading":null,"bab":"XIV","bab_heading":"KETENTUAN PIDANA","sort_order":207}', '/akn/id/act/uu/2022/27#pasal-71', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_72', 'Pasal 72', 'ARTICLE', '', NULL, '{"law_id":"uu_2022_27","pasal":"72","heading":null,"bab":"XIV","bab_heading":"KETENTUAN PIDANA","sort_order":213}', '/akn/id/act/uu/2022/27#pasal-72', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_73', 'Pasal 73', 'ARTICLE', 'Ketentuan sebagaimana dimaksud dalam Pasal 71 dan Pasal 72 juga berlaku dalam hal penjatuhan pidana tambahan berupa pembayaran ganti kerugian.', NULL, '{"law_id":"uu_2022_27","pasal":"73","heading":null,"bab":"XIV","bab_heading":"KETENTUAN PIDANA","sort_order":216}', '/akn/id/act/uu/2022/27#pasal-73', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_74', 'Pasal 74', 'ARTICLE', 'Pada saat Undang-Undang ini mulai berlaku, Pengendali Data Pribadi, Prosesor Data Pribadi, dan pihak lain yang terkait dengan pemrosesan Data Pribadi, wajib menyesuaikan dengan ketentuan pemrosesan Data Pribadi berdasarkan Undang-Undang ini paling lama 2 (dua) tahun sejak Undang-Undang ini diundangkan.', NULL, '{"law_id":"uu_2022_27","pasal":"74","heading":null,"bab":"XV","bab_heading":"KETENTUAN PERALIHAN","sort_order":218}', '/akn/id/act/uu/2022/27#pasal-74', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_75', 'Pasal 75', 'ARTICLE', 'Pada saat Undang-Undang ini mulai berlaku, semua ketentuan peraturan perundang-undangan yang mengatur mengenai Pelindungan Data Pribadi, dinyatakan masih tetap berlaku sepanjang tidak bertentangan dengan ketentuan dalam Undang-Undang ini.', NULL, '{"law_id":"uu_2022_27","pasal":"75","heading":null,"bab":"XV","bab_heading":"KETENTUAN PERALIHAN","sort_order":219}', '/akn/id/act/uu/2022/27#pasal-75', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2022_27_pasal_76', 'Pasal 76', 'ARTICLE', 'Undang-Undang ini mulai berlaku pada tanggal diundangkan.', NULL, '{"law_id":"uu_2022_27","pasal":"76","heading":null,"bab":"XVI","bab_heading":"KETENTUAN PENUTUP","sort_order":221}', '/akn/id/act/uu/2022/27#pasal-76', 'berlaku', NULL, NULL, NULL, NULL);
