INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2006_17_pasal_49', 'Pasal 49', 'ARTICLE', 'Importir, eksportir, pengusaha tempat penimbunan sementara, pengusaha tempat penimbunan berikat, pengusaha pengurusan jasa kepabeanan, atau pengusaha pengangkutan wajib menyelenggarakan pembukuan.', NULL, '{"law_id":"uu_2006_17","pasal":"49","heading":null,"bab":null,"bab_heading":null,"sort_order":247}', '/akn/id/act/uu/2006/17#pasal-49', 'berlaku', NULL, NULL, NULL, NULL);
