INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2006_17_pasal_54', 'Pasal 54', 'ARTICLE', 'Atas permintaan pemilik atau pemegang hak atas merek atau hak cipta, ketua pengadilan niaga dapat mengeluarkan perintah tertulis kepada pejabat bea dan cukai untuk menangguhkan sementara waktu pengeluaran barang impor atau ekspor dari kawasan pabean yang berdasarkan bukti yang cukup, diduga merupakan hasil pelanggaran merek dan hak cipta yang dilindungi di Indonesia.', NULL, '{"law_id":"uu_2006_17","pasal":"54","heading":null,"bab":null,"bab_heading":null,"sort_order":271}', '/akn/id/act/uu/2006/17#pasal-54', 'berlaku', NULL, NULL, NULL, NULL);
