INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2006_17_pasal_60', 'Pasal 60', 'ARTICLE', 'Dalam keadaan tertentu, importir, eksportir, atau pemilik barang impor atau ekspor dapat mengajukan permintaan kepada ketua pengadilan niaga untuk memerintahkan secara tertulis kepada pejabat bea dan cukai agar mengakhiri penangguhan sebagaimana dimaksud dalam Pasal 54 dengan menyerahkan jaminan yang sama sebagaimana dimaksud dalam Pasal 55 huruf d.', NULL, '{"law_id":"uu_2006_17","pasal":"60","heading":null,"bab":null,"bab_heading":null,"sort_order":289}', '/akn/id/act/uu/2006/17#pasal-60', 'berlaku', NULL, NULL, NULL, NULL);
