INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2006_17_pasal_78', 'Pasal 78', 'ARTICLE', 'Pejabat bea dan cukai berwenang untuk mengunci, menyegel, dan/atau melekatkan tanda pengaman yang diperlukan terhadap barang impor yang belum diselesaikan kewajiban pabeannya dan barang ekspor atau barang lain yang harus diawasi menurut Undang-Undang ini yang berada di sarana pengangkut, tempat penimbunan atau tempat lain.', NULL, '{"law_id":"uu_2006_17","pasal":"78","heading":null,"bab":null,"bab_heading":null,"sort_order":307}', '/akn/id/act/uu/2006/17#pasal-78', 'berlaku', NULL, NULL, NULL, NULL);
