INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2006_17_pasal_95', 'Pasal 95', 'ARTICLE', 'Orang yang berkeberatan terhadap penetapan Direktur Jenderal atas tarif dan nilai pabean sebagaimana dimaksud dalam Pasal 17 ayat (2), keputusan Direktur Jenderal sebagaimana dimaksud dalam Pasal 93 ayat (2), Pasal 93A ayat (4), atau Pasal 94 ayat (2) dapat mengajukan permohonan banding kepada Pengadilan Pajak dalam jangka waktu 60 (enam puluh) hari sejak tanggal penetapan atau tanggal keputusan, setelah pungutan yang terutang dilunasi.', NULL, '{"law_id":"uu_2006_17","pasal":"95","heading":null,"bab":null,"bab_heading":null,"sort_order":382}', '/akn/id/act/uu/2006/17#pasal-95', 'berlaku', NULL, NULL, NULL, NULL);
