INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2006_17_pasal_102b', 'Pasal 102B', 'ARTICLE', 'Pelanggaran sebagaimana dimaksud dalam Pasal 102 dan Pasal 102A yang mengakibatkan terganggunya sendi-sendi perekonomian negara dipidana dengan pidana penjara paling singkat 5 (lima) tahun dan pidana penjara paling lama 20 (dua puluh) tahun dan pidana denda paling sedikit Rp5.000.000.000,00 (lima miliar rupiah) dan paling banyak Rp100.000.000.000,00 (seratus miliar rupiah).', NULL, '{"law_id":"uu_2006_17","pasal":"102B","heading":null,"bab":null,"bab_heading":null,"sort_order":394}', '/akn/id/act/uu/2006/17#pasal-102B', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2006_17_pasal_102c', 'Pasal 102C', 'ARTICLE', 'Dalam hal perbuatan tindak pidana sebagaimana diatur dalam Pasal 102, Pasal 102A, Pasal 102B dilakukan oleh pejabat dan aparat penegak hukum, pidana yang dijatuhkan dengan pidana sebagaimana ancaman pidana dalam Undang-Undang ini ditambah 1/3 (satu pertiga).', NULL, '{"law_id":"uu_2006_17","pasal":"102C","heading":null,"bab":null,"bab_heading":null,"sort_order":395}', '/akn/id/act/uu/2006/17#pasal-102C', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2006_17_pasal_102d', 'Pasal 102D', 'ARTICLE', 'Setiap orang yang mengangkut barang tertentu yang tidak sampai ke kantor pabean tujuan dan tidak dapat membuktikan bahwa hal tersebut di luar kemampuannya dipidana dengan pidana penjara paling singkat 1 (satu) tahun dan pidana penjara paling lama 5 (lima) tahun dan/atau pidana denda paling sedikit Rp10.000.000.00 (sepuluh juta rupiah) dan paling banyak Rp1.000.000.000.00 (satu miliar rupiah).', NULL, '{"law_id":"uu_2006_17","pasal":"102D","heading":null,"bab":null,"bab_heading":null,"sort_order":396}', '/akn/id/act/uu/2006/17#pasal-102D', 'berlaku', NULL, NULL, NULL, NULL);
