INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2016_20_pasal_43', 'Pasal 43', 'ARTICLE', 'Pemilik Merek terdaftar yang telah memberikan Lisensi kepada pihak lain sebagaimana dimaksud dalam pasal 42 ayat (1) tetap dapat menggunakan sendiri atau memberikan Lisensi kepada pihak ketiga untuk menggunakan Merek tersebut, kecuali diperjanjikan lain.', NULL, '{"law_id":"uu_2016_20","pasal":"43","heading":null,"bab":null,"bab_heading":null,"sort_order":176}', '/akn/id/act/uu/2016/20#pasal-43', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2016_20_pasal_44', 'Pasal 44', 'ARTICLE', 'Penggunaan Merek terdaftar di wilayah Negara Kesatuan Republik Indonesia oleh penerima Lisensi dianggap sama dengan penggunaan Merek tersebut di wilayah Negara Kesatuan Republik Indonesia oleh pemilik Merek.', NULL, '{"law_id":"uu_2016_20","pasal":"44","heading":null,"bab":null,"bab_heading":null,"sort_order":177}', '/akn/id/act/uu/2016/20#pasal-44', 'diubah', NULL, NULL, NULL, NULL);
