INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2016_20_pasal_102', 'Pasal 102', 'ARTICLE', 'Setiap Crang yang memperdagangkan barang dan/atau jasa dan/atau produk yang diketahui atau patut diduga mengetahui bahwa barang dan/atau jasa dan/atau produk tersebut merupakan hasil tindak pidana sebagaimana dimaksud dalam Pasal 100 dan Pasal 101 dipidana dengan pidana kurungan paling lama 1 (satu) tahun atau denda paling banyak Rp200.000.000,00 (dua ratus juta rupiah).', NULL, '{"law_id":"uu_2016_20","pasal":"102","heading":null,"bab":"XVIII","bab_heading":"KETENTUAN PIDANA","sort_order":400}', '/akn/id/act/uu/2016/20#pasal-102', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2016_20_pasal_103', 'Pasal 103', 'ARTICLE', 'Tindak pidana sebagaimana dimaksud dalam Pasal 100 sampai dengan Pasal 102 merupakan delik aduan.', NULL, '{"law_id":"uu_2016_20","pasal":"103","heading":null,"bab":"XVIII","bab_heading":"KETENTUAN PIDANA","sort_order":401}', '/akn/id/act/uu/2016/20#pasal-103', 'diubah', NULL, NULL, NULL, NULL);
