INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2016_20_pasal_105', 'Pasal 105', 'ARTICLE', 'Sengketa Merek yang masih dalam proses di pengadilan pada saat Undang-Undang ini berlaku tetap diproses berdasarkan Undang-Undang Nomor 15 TAHUN 2001 tentang Merek sampai mendapat putusan yang mempunyai kekuatan hukum tetap.', NULL, '{"law_id":"uu_2016_20","pasal":"105","heading":null,"bab":"XIX","bab_heading":"KETENTUAN PERALIHAN","sort_order":407}', '/akn/id/act/uu/2016/20#pasal-105', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2016_20_pasal_106', 'Pasal 106', 'ARTICLE', 'Pada saat Undang-Undang ini mulai berlaku, semua peraturan perurdang-undangan yang merupakan peraturan pelaksanaan dari Undang-Undang Nomor 15 TAHUN 2001 tentang Merek (Lembaran Negara Republik Indonesia Tahun 2001 NOMOR 110 Tambahan Lembaran Negara Republik Indonesia Nomor 4131), dinyatakan masih tetap berlaku sepanjang tidak bertentangan dengan ketentuan dalam Undang-Undang ini.', NULL, '{"law_id":"uu_2016_20","pasal":"106","heading":null,"bab":"XX","bab_heading":"KETENTUAN PENUTUP","sort_order":409}', '/akn/id/act/uu/2016/20#pasal-106', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2016_20_pasal_107', 'Pasal 107', 'ARTICLE', 'Pada Saat Undang-Undang ini mulai berlaku, Undang-Undang Nomor 15 TAHUN 2001 tentang Merek (Lembaran Negara Republik Indonesia Tahun 2001 Nomor 110, Tambahan Lembaran Negara Republik Indonesia Nomor 4131) dicabut dan dinyazakan tidak berlaku.', NULL, '{"law_id":"uu_2016_20","pasal":"107","heading":null,"bab":"XX","bab_heading":"KETENTUAN PENUTUP","sort_order":410}', '/akn/id/act/uu/2016/20#pasal-107', 'diubah', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_2016_20_pasal_108', 'Pasal 108', 'ARTICLE', 'Peraturan pelaksanaan dari Undang-Undang ini harus ditetapkan paling lama 2 (dua) tahun terhitung sejak Undang-Undang ini diundangkan.', NULL, '{"law_id":"uu_2016_20","pasal":"108","heading":null,"bab":"XX","bab_heading":"KETENTUAN PENUTUP","sort_order":411}', '/akn/id/act/uu/2016/20#pasal-108', 'diubah', NULL, NULL, NULL, NULL);
