INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_12', 'Pasal 12', 'ARTICLE', 'Setiap orang yang melakukan tindak pidana sebagaimana dimaksud dalam Pasal 419, Pasal 420, Pasal 423, Pasal 425, atau Pasal 435 Kitab Undang-undang Hukum Pidana, dipi dana dengan pidana penjara seumur hidup atau pidana penjar a paling singkat 4 (empat) tahun dan paling lama 20 (dua puluh) tahun dan denda paling sedikit Rp 200.000.000,00 (dua ratus juta rupiah) dan paling banyak 1.000.000.000,00 (satu milyar rupiah).', NULL, '{"law_id":"uu_1999_31","pasal":"12","heading":null,"bab":"II","bab_heading":"TINDAK PIDANA KORUPSI","sort_order":17}', '/akn/id/act/uu/1999/31#pasal-12', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_13', 'Pasal 13', 'ARTICLE', 'Setiap orang yang memberi hadiah at au janji kepada pegawai negeri dengan mengingat kekuasaan atau wewenang yang melekat pada jabatan atau kedudukannya, atau oleh pemberi hadiah atau janji dianggap melekat pada jabatan at au kedudukan terse but, dipidana dengan pidana penjara pa ling lama 3 (tiga) tahun dan atau denda paling banyak 150.000.000,00 (seratus lima puluh juta rupiah).', NULL, '{"law_id":"uu_1999_31","pasal":"13","heading":null,"bab":"II","bab_heading":"TINDAK PIDANA KORUPSI","sort_order":18}', '/akn/id/act/uu/1999/31#pasal-13', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_14', 'Pasal 14', 'ARTICLE', 'Setiap orang yang melanggar kete ntuan Undang-unda ng yang secara tegas menyatakan bahwa pela nggaran terhadap ketentuan Undang-undang tersebut sebagai tindak pidana korupsi berlaku ketentuan yang diatur dalam Undang-undang ini.', NULL, '{"law_id":"uu_1999_31","pasal":"14","heading":null,"bab":"II","bab_heading":"TINDAK PIDANA KORUPSI","sort_order":19}', '/akn/id/act/uu/1999/31#pasal-14', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_15', 'Pasal 15', 'ARTICLE', 'Setiap orang yang me lakukan percobaan, pembantuan, atau pemufakatan jahat untuk melakukan ti ndak pidana korups i, dipidana dengan pidana yang sama sebagaimana dimaksud Pasal 2, Pasal 3, Pasal 5 sampai dengan Pasal 14.', NULL, '{"law_id":"uu_1999_31","pasal":"15","heading":null,"bab":"II","bab_heading":"TINDAK PIDANA KORUPSI","sort_order":20}', '/akn/id/act/uu/1999/31#pasal-15', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_16', 'Pasal 16', 'ARTICLE', 'Setiap orang di luar wilayah negara Republik Indonesia yang memberikan bantuan, kesempatan , sarana, atau keterangan untuk terjadi` tindak pidana korupsi di pidana dengan pi dana yang sama sebagai pelaku tindak pidana kor upsi sebagaimana dimaksud dalam Pasal 2, Pasal 3, Pasal 5 sampai dengan Pasal 14.', NULL, '{"law_id":"uu_1999_31","pasal":"16","heading":null,"bab":"II","bab_heading":"TINDAK PIDANA KORUPSI","sort_order":21}', '/akn/id/act/uu/1999/31#pasal-16', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_17', 'Pasal 17', 'ARTICLE', 'PRESIDEN Selain dapat dijatuhi pidana se bagaimana dimaksud dalam Pasal 2, Pasal 3, Pasal 5 sampai dengan Pa sal 14, terdakwa dapat dijatuhi pidana tambahan sebagaimana dimaksud dalam Pasal 18.', NULL, '{"law_id":"uu_1999_31","pasal":"17","heading":null,"bab":"II","bab_heading":"TINDAK PIDANA KORUPSI","sort_order":22}', '/akn/id/act/uu/1999/31#pasal-17', 'berlaku', NULL, NULL, NULL, NULL);
