INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_21', 'Pasal 21', 'ARTICLE', 'Setiap orang yang denga n sengaja mencegah, merintangi, atau menggagalkan secara langsung at au tidak langsung penyidikan, penuntutan, dan pemeriks aan di sidang pengadilan terhadap tersangka dan terdakwa ataupun para saksi dalam perkara korupsi, dipidana dengan pidana penjara paling singkat 3 (tiga) tahun dan paling lama 12 (dua belas) tahun dan atau de nda paling sedikit Rp. 150.000.000,00 (seratus lima puluh juta rupiah ) dan paling banya k Rp 600.000.000,00 (enam ratus juta rupiah).', NULL, '{"law_id":"uu_1999_31","pasal":"21","heading":null,"bab":"III","bab_heading":"TINDAK PIDANA LAIN YANG BERKAITAN DENGAN TINDAK PIDANA KORUPSI","sort_order":42}', '/akn/id/act/uu/1999/31#pasal-21', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_22', 'Pasal 22', 'ARTICLE', 'Setiap orang sebagaimana dimaksud dalam Pasal 28, Pasal 29, Pasal 35, atau Pasal 36 yang denga n sengaja tidak memberi keterangan atau memberi keterangan yang tidak benar, dipidana dengan pidana penjara paling singkat 3 (tiga) tahun dan pali ng lama 12 (dua belas) tahun dan atau denda paling sedikit Rp 150. 000.000,00 (seratus lima puluh juta rupiah) dan paling banyak Rp 600.000.000,00 (enam ratus juta rupiah).', NULL, '{"law_id":"uu_1999_31","pasal":"22","heading":null,"bab":"III","bab_heading":"TINDAK PIDANA LAIN YANG BERKAITAN DENGAN TINDAK PIDANA KORUPSI","sort_order":43}', '/akn/id/act/uu/1999/31#pasal-22', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_23', 'Pasal 23', 'ARTICLE', 'Dalam perkara korupsi, pelanggaran terhadap ketentuan sebagaimana dimaksud dalam Pasal 220, Pasal 231, Pasal 421, Pasal 422, Pasal 429 atau Pasal 430 Kitab Undang-undang Hukum Pidana, di pidana dengan pidana penjara paling singka t 1 (satu) tahun dan paling lama 6 (enam) tahun dan atau denda paling sedik it Rp 50.000.000,00 (lima puluh juta rupiah) dan paling banyak Rp. 300.000.000,00 (tiga ratus juta rupiah).', NULL, '{"law_id":"uu_1999_31","pasal":"23","heading":null,"bab":"III","bab_heading":"TINDAK PIDANA LAIN YANG BERKAITAN DENGAN TINDAK PIDANA KORUPSI","sort_order":44}', '/akn/id/act/uu/1999/31#pasal-23', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_24', 'Pasal 24', 'ARTICLE', 'Saksi yang tidak memenuhi ketent uan sebagaimana dimaksud dalam Pasal 31, dipidana dengan pidana penjara paling lama 3 (tiga) tahun dan atau denda paling banyak Rp 150. 000.000,000 (seratus lima puluh juta rupiah).', NULL, '{"law_id":"uu_1999_31","pasal":"24","heading":null,"bab":"III","bab_heading":"TINDAK PIDANA LAIN YANG BERKAITAN DENGAN TINDAK PIDANA KORUPSI","sort_order":45}', '/akn/id/act/uu/1999/31#pasal-24', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_25', 'Pasal 25', 'ARTICLE', 'PRESIDEN Penyidikan, penuntutan, dan pemeriksaan di sidang pengadilan dalam perkara tindak pidana kor upsi harus didahulukan dari perkara lain guna penyelesaian secepatnya.', NULL, '{"law_id":"uu_1999_31","pasal":"25","heading":null,"bab":"IV","bab_heading":"PENYIDIKAN, PENUNTUTAN, DAN PEMERIKSAAN DI SIDANG PENGADILAN","sort_order":47}', '/akn/id/act/uu/1999/31#pasal-25', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_26', 'Pasal 26', 'ARTICLE', 'Penyidikan, penuntutan, dan pemeriksaan di sidang pengadilan terhadap tindak pidana korupsi, dilakukan berdasarkan hukum acara pidana yang berlaku, kecuali ditentukan lain dalam Undang-undang ini.', NULL, '{"law_id":"uu_1999_31","pasal":"26","heading":null,"bab":"IV","bab_heading":"PENYIDIKAN, PENUNTUTAN, DAN PEMERIKSAAN DI SIDANG PENGADILAN","sort_order":48}', '/akn/id/act/uu/1999/31#pasal-26', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_27', 'Pasal 27', 'ARTICLE', 'Dalam hal ditemukan tindak pida na korupsi yang sulit pembuktiannya, maka dapat dibentuk tim gabungan di bawah koordinasi Jaksa Agung.', NULL, '{"law_id":"uu_1999_31","pasal":"27","heading":null,"bab":"IV","bab_heading":"PENYIDIKAN, PENUNTUTAN, DAN PEMERIKSAAN DI SIDANG PENGADILAN","sort_order":49}', '/akn/id/act/uu/1999/31#pasal-27', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_28', 'Pasal 28', 'ARTICLE', 'Untuk kepentingan penyidikan, tersangka wajib memberikan keterangan tentang seluruh harta be ndanya dan harta benda istri atau suami, anak, dan harta benda setiap orang atau korporasi yang dike tahui dan atau yang diduga mempunyai hubungan dengan tindak pi dana korupsi yang dilakukan tersangka.', NULL, '{"law_id":"uu_1999_31","pasal":"28","heading":null,"bab":"IV","bab_heading":"PENYIDIKAN, PENUNTUTAN, DAN PEMERIKSAAN DI SIDANG PENGADILAN","sort_order":50}', '/akn/id/act/uu/1999/31#pasal-28', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_29', 'Pasal 29', 'ARTICLE', '', NULL, '{"law_id":"uu_1999_31","pasal":"29","heading":null,"bab":"IV","bab_heading":"PENYIDIKAN, PENUNTUTAN, DAN PEMERIKSAAN DI SIDANG PENGADILAN","sort_order":51}', '/akn/id/act/uu/1999/31#pasal-29', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_30', 'Pasal 30', 'ARTICLE', 'Penyidik berhak membuka, memeriksa, dan menyita surat dan kiriman melalui pos, telekomunikasi atau alat lainnya yang dicurigai mempunyai hubungan dengan perkara tindak pidana korupsi yang sedang diperiksa.', NULL, '{"law_id":"uu_1999_31","pasal":"30","heading":null,"bab":"IV","bab_heading":"PENYIDIKAN, PENUNTUTAN, DAN PEMERIKSAAN DI SIDANG PENGADILAN","sort_order":57}', '/akn/id/act/uu/1999/31#pasal-30', 'berlaku', NULL, NULL, NULL, NULL);
