INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_33', 'Pasal 33', 'ARTICLE', 'Dalam hak tersangka meninggal dunia pada saat dilakukan penyidikan, sedangkan secara nyata telah ada ke rugian keuangan negara, maka penyidik segera menyerahka n berkas perkara has il penyidikan tersebut kepada Jaksa Pengacara Negara atau diserahkan kepada instansi yang dirugikan untuk dilakukan gugatan perdata terhadap ahli warisnya.', NULL, '{"law_id":"uu_1999_31","pasal":"33","heading":null,"bab":"IV","bab_heading":"PENYIDIKAN, PENUNTUTAN, DAN PEMERIKSAAN DI SIDANG PENGADILAN","sort_order":64}', '/akn/id/act/uu/1999/31#pasal-33', 'berlaku', NULL, NULL, NULL, NULL);
