INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_36', 'Pasal 36', 'ARTICLE', 'Kewajiban memberikan kesaksian sebagaimana dimaksud dalam Pasal 35 berlaku juga terhadap mereka yang menurut pekerjaan, harkat dan martabat atau jabatannya diwaji bkan menyimpan rahasia, kecuali petugas agama yang menurut keyakinannya harus menyimpan rahasia.', NULL, '{"law_id":"uu_1999_31","pasal":"36","heading":null,"bab":"IV","bab_heading":"PENYIDIKAN, PENUNTUTAN, DAN PEMERIKSAAN DI SIDANG PENGADILAN","sort_order":70}', '/akn/id/act/uu/1999/31#pasal-36', 'berlaku', NULL, NULL, NULL, NULL);
