INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_39', 'Pasal 39', 'ARTICLE', 'Jaksa Agung mengkoordinasikan dan mengendalikan penyidikan, penyidikan, dan penunt utan tindak pidana korupsi yang dilakukan bersama-sama oleh orang yang tunduk pada Peradilan Umum dan Peradilan Militer.', NULL, '{"law_id":"uu_1999_31","pasal":"39","heading":null,"bab":"IV","bab_heading":"PENYIDIKAN, PENUNTUTAN, DAN PEMERIKSAAN DI SIDANG PENGADILAN","sort_order":85}', '/akn/id/act/uu/1999/31#pasal-39', 'berlaku', NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_40', 'Pasal 40', 'ARTICLE', 'Dalam hal terdapat cukup alasan untuk mengajukan perkara korupsi di lingkungan Peradilan Militer, maka ke tentuan sebagaimana dimaksud dalam Pasal 123 ayat (1) huruf g Undang-undang Nomor 31 Tahun 1997 tentang Peradilan Militer tidak dapat diberlakukan.', NULL, '{"law_id":"uu_1999_31","pasal":"40","heading":null,"bab":"IV","bab_heading":"PENYIDIKAN, PENUNTUTAN, DAN PEMERIKSAAN DI SIDANG PENGADILAN","sort_order":86}', '/akn/id/act/uu/1999/31#pasal-40', 'berlaku', NULL, NULL, NULL, NULL);
