INSERT OR IGNORE INTO nodes (id, name, type, content, description, metadata, frbr_uri, status, number, year, zh_title, zh_summary) VALUES ('uu_1999_31_pasal_44', 'Pasal 44', 'ARTICLE', 'Pada saat mulai berlakunya U ndang-undang ini, ma ka Undang-undang Nomor 3 Tahun 1971 tentang Pemberan tasan Tindak Pidana Korupsi (Lembaran Negara Nomor 19, Tamb ahan Lembaran Negara Nomor 2958), dinyatakan tidak berlaku.', NULL, '{"law_id":"uu_1999_31","pasal":"44","heading":null,"bab":"VII","bab_heading":"KETENTUAN PENUTUP","sort_order":104}', '/akn/id/act/uu/1999/31#pasal-44', 'berlaku', NULL, NULL, NULL, NULL);
